window.TI_BUNDLE = {"world": {"planet": {"code": "X-01", "title": "Планета X-01", "mapWidth": 1000, "mapHeight": 620, "startSector": "sector-01"}, "chapters": [{"id": 1, "title": "Глава 1. Планета X-01", "shortTitle": "Глава 1", "grade": "6 класс", "startSector": "sector-01"}], "points": {"normal": 100, "complex": 150, "extra": 50}, "intro": {"title": "Экспедиция на планету X-01", "paragraphs": ["Дальний зонд вышел на орбиту неизвестной планеты. Её обозначение — X-01. Атмосфера пригодна для дыхания, на поверхности есть океан и суша.", "Сведений почти нет: неизвестно, сколько на планете материков, где текут реки и как распределены осадки. Приборы различают лишь небольшой участок берега.", "Вы — научный руководитель экспедиции. Ваша задача: изучать территории, применять знания о рельефе, климате и водах, делать выводы и открывать новые районы.", "Планета необычная, но законы природы на ней те же: вода течёт вниз, горы влияют на осадки, климат зависит от условий местности."]}, "about": {"title": "Об игре", "paragraphs": ["TERRA INCOGNITA — образовательная игра по географии. Игрок исследует вымышленную планету и открывает её территории, решая задачи о рельефе, климате и водах.", "Неверный ответ не штрафуется: игра объясняет решение и предлагает попробовать снова. Главная награда — новые территории и записи в журнале экспедиции.", "Прогресс хранится только в вашем браузере. Его можно перенести на другое устройство через экспорт и импорт файла."]}, "mission": "Миссия: восстановить географическую картину планеты X-01 — найти все территории и понять, как рельеф, климат и воды связаны между собой.", "knownFacts": ["Планета вращается, как Земля: стороны горизонта на схемах обозначены так же — север вверху, восток справа.", "Полярная область планеты находится на севере."], "achievements": [{"id": "first-contact", "name": "Первый контакт", "description": "Исследован стартовый сектор.", "condition": {"type": "sectorExplored", "sector": "sector-01"}}, {"id": "cartographer", "name": "Картограф", "description": "Исследованы три территории.", "condition": {"type": "exploredCount", "n": 3}}, {"id": "relief-explorer", "name": "Исследователь рельефа", "description": "Завершено исследование горного сектора.", "condition": {"type": "sectorExplored", "sector": "sector-02"}}, {"id": "climatologist", "name": "Климатолог", "description": "Решены три задачи о климате.", "condition": {"type": "topicTasks", "topic": "climate", "n": 3}}, {"id": "first-discoveries", "name": "Первые открытия", "description": "Найдено пять географических открытий.", "condition": {"type": "discoveryCount", "n": 5}}, {"id": "thorough", "name": "Дотошный исследователь", "description": "Один сектор изучен полностью.", "condition": {"type": "fullCount", "n": 1}}, {"id": "whole-planet", "name": "Вся планета", "description": "Исследованы все 12 территорий.", "condition": {"type": "exploredCount", "n": 12}}]}, "sectors": [{"id": "sector-01", "name": "Берег первого контакта", "type": "coastal_plain", "description": "Исследовательский аппарат обнаружил участок суши, омываемый океаном. Рельеф преимущественно равнинный. В центральной части территории заметны возвышенности. Сведения о климате и водной сети отсутствуют.", "geo": "Приморская равнина с возвышенностями в глубине суши; океан на западе.", "requires": [], "taskIds": ["task-001", "task-002", "task-003", "task-004"], "discoveries": ["discovery-001"], "poly": "330,332 400,352 380,400 420,450 340,480 250,470 200,400 230,350", "center": [310, 408], "journal": "Исследован «Берег первого контакта». Вода течёт с возвышенностей к океану, значит речная сеть начинается в глубине суши. На северо-востоке виден горный массив."}, {"id": "sector-02", "name": "Горный барьер", "type": "mountains", "description": "На северо-востоке от стартовой территории обнаружена протяжённая горная система. Высоты постепенно увеличиваются к центральной части массива. Климатические сведения отсутствуют.", "geo": "Высокий хребет, вытянутый с севера на юг; на него набегают влажные ветры с запада.", "requires": ["sector-01"], "taskIds": ["task-005", "task-006", "task-007", "task-008"], "discoveries": ["discovery-002"], "poly": "470,146 560,138 590,240 572,340 520,404 470,330 486,240", "center": [525, 262], "journal": "Исследован «Горный барьер». Западный склон получает много осадков, там начинаются реки. Хребет влияет на климат всего материка."}, {"id": "sector-03", "name": "Теневая равнина", "type": "rain_shadow_plain", "description": "За горной системой обнаружена обширная равнина. Первичные данные указывают на небольшое количество осадков. Необходимо установить вероятную причину засушливости.", "geo": "Равнина с малым количеством осадков на подветренной стороне хребта.", "requires": ["sector-02"], "taskIds": ["task-009", "task-010", "task-011", "task-012"], "discoveries": ["discovery-003"], "poly": "560,138 660,150 700,250 690,330 660,350 572,340 590,240", "center": [632, 245], "journal": "Исследована «Теневая равнина». Горы задерживают влагу с запада, поэтому за хребтом выпадает мало осадков: здесь образуется дождевая тень."}, {"id": "sector-04", "name": "Речная долина", "type": "river_valley", "description": "У подножия гор, к югу и востоку от стартового берега, обнаружено вытянутое понижение. Спутник фиксирует блеск воды на его дне. Верхний конец долины лежит на севере у гор, нижний — на юге у океана.", "geo": "Долина реки, текущей с гор на юг, к океану.", "requires": ["sector-01"], "taskIds": ["task-013", "task-014", "task-015", "task-016"], "discoveries": ["discovery-004"], "poly": "400,352 470,330 520,404 560,452 500,470 420,450 380,400", "center": [468, 410], "journal": "Исследована «Речная долина». Река начинается в горах и течёт на юг. Сток подтверждает связь гор, рек и океана."}, {"id": "sector-05", "name": "Внутренняя котловина", "type": "basin", "description": "К юго-востоку от гор обнаружено обширное замкнутое понижение, окружённое возвышенностями. Реки с горных склонов направляются к его центру. Выход к океану не найден.", "geo": "Бессточная котловина: вода собирается в центре и не уходит к океану.", "requires": ["sector-02", "sector-04"], "taskIds": ["task-017", "task-018", "task-019", "task-020"], "discoveries": ["discovery-005"], "poly": "572,340 660,350 690,330 710,430 640,478 560,452 520,404", "center": [630, 413], "journal": "Исследована «Внутренняя котловина». Вода не уходит к океану: она копится в озере и испаряется, поэтому озеро солёное."}, {"id": "sector-06", "name": "Лесной склон", "type": "forest", "description": "К западу от горного барьера, на предгорьях, обнаружен тёмный массив растительности. Он обращён к океану, откуда дуют ветры.", "geo": "Влажные предгорья на наветренной стороне гор, покрытые лесом.", "requires": ["sector-02"], "taskIds": ["task-021", "task-022", "task-023", "task-024"], "discoveries": ["discovery-006"], "poly": "318,126 380,150 470,146 486,240 470,330 400,352 330,332 298,240", "center": [392, 240], "journal": "Исследован «Лесной склон». Обилие осадков на наветренных предгорьях создало влажный лес. С подъёмом в гору лес сменяется лугами и скалами."}, {"id": "sector-07", "name": "Вулканическое нагорье", "type": "volcanic", "description": "На юго-востоке материка обнаружен район с коническими горами и тёмными застывшими потоками. Над несколькими вершинами поднимается пар.", "geo": "Цепочка вулканов вдоль линии разломов земной коры.", "requires": ["sector-05"], "taskIds": ["task-025", "task-026", "task-027", "task-028"], "discoveries": ["discovery-007"], "poly": "690,330 800,330 840,410 790,490 710,430", "center": [755, 410], "journal": "Исследовано «Вулканическое нагорье». Вулканы выстроены цепочкой вдоль разлома. Вулканический пепел делает почвы плодородными."}, {"id": "sector-08", "name": "Остров Дальний", "type": "island", "description": "В океане к западу от материка обнаружен остров. Он отделён от суши проливом шириной в несколько сотен километров. В центре острова поднимается холм.", "geo": "Остров с морским климатом посреди океана.", "requires": ["sector-12"], "taskIds": ["task-029", "task-030", "task-031", "task-032"], "discoveries": ["discovery-008"], "poly": "90,190 150,170 205,200 215,260 165,300 105,280 80,235", "center": [148, 238], "journal": "Исследован «Остров Дальний». Океан смягчает климат: лето прохладное, зима тёплая, осадки обильные."}, {"id": "sector-09", "name": "Полярная область", "type": "polar", "description": "На севере материка зафиксированы обширные белые поверхности. Солнце там стоит низко над горизонтом даже в полдень.", "geo": "Холодная область на севере, покрытая снегом и льдом.", "requires": ["sector-06"], "taskIds": ["task-033", "task-034", "task-035", "task-036"], "discoveries": ["discovery-009"], "poly": "318,126 380,150 470,146 560,138 660,150 790,142 790,92 720,50 580,34 430,40 320,70", "center": [550, 92], "journal": "Исследована «Полярная область». Низкое Солнце, снег и лёд создают холодный климат. В центре плато лежит ледяной купол."}, {"id": "sector-10", "name": "Каменистая пустыня", "type": "desert", "description": "К востоку от Теневой равнины обнаружено сухое плато с участками песка. Растительность почти не видна.", "geo": "Пустыня в глубине суши, далеко от океана и за горами.", "requires": ["sector-03"], "taskIds": ["task-037", "task-038", "task-039", "task-040"], "discoveries": ["discovery-010"], "poly": "660,150 790,142 830,240 800,330 690,330 700,250", "center": [748, 240], "journal": "Исследована «Каменистая пустыня». Сухой воздух и ясное небо дают резкие суточные перепады температуры. Жизнь возможна там, где близко грунтовые воды."}, {"id": "sector-11", "name": "Дельта Серебряной реки", "type": "delta", "description": "У южного побережья русло реки разветвляется на множество рукавов. Береговая линия здесь неровная, с островками наносов.", "geo": "Низменная дельта в устье реки, текущей из Речной долины.", "requires": ["sector-04"], "taskIds": ["task-041", "task-042", "task-043", "task-044"], "discoveries": ["discovery-011"], "poly": "340,480 420,450 500,470 560,452 560,520 480,560 390,548", "center": [470, 508], "journal": "Исследована «Дельта Серебряной реки». Река теряет скорость в устье и откладывает наносы. Так растёт суша. На океан у берега влияет тёплое течение."}, {"id": "sector-12", "name": "Тёплое течение", "type": "ocean_current", "description": "У юго-западного берега спутник зафиксировал полосу воды необычной температуры. Она вытянута вдоль побережья с юга на север. К северу от неё виден остров.", "geo": "Морское течение вдоль западного берега материка.", "requires": ["sector-11"], "taskIds": ["task-045", "task-046", "task-047", "task-048"], "discoveries": ["discovery-012"], "poly": "60,400 170,380 200,400 250,470 240,560 120,570 50,500", "center": [145, 480], "journal": "Исследовано «Тёплое течение». Течение несёт тёплую воду с юга на север и смягчает климат побережья."}], "tasks": [{"id": "task-001", "sectorId": "sector-01", "type": "multiple_choice", "topic": "orientation", "title": "Ориентирование", "description": "На схеме отмечены исследовательская станция и холм. Север на схеме вверху, восток справа (см. компас).", "question": "В каком направлении от станции расположен холм?", "hint": "Найди на схеме станцию и холм. Холм выше и правее станции. Сравни с компасом.", "explanation": "Холм находится выше (севернее) и правее (восточнее) станции, значит, он лежит на северо-востоке. Стороны горизонта помогают держать направление, когда нет дорог и ориентиров.", "extra": false, "complex": false, "options": ["На северо-востоке", "На юго-востоке", "На северо-западе", "На юго-западе"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 80, "h": 180, "c": "water"}, {"t": "text", "x": 40, "y": 90, "s": "Океан"}, {"t": "dot", "x": 150, "y": 120, "label": "Станция"}, {"t": "dot", "x": 235, "y": 50, "label": "Холм"}]}}, {"id": "task-002", "sectorId": "sector-01", "type": "map_click", "topic": "relief", "title": "Где искать исток реки", "description": "Нужно выбрать участок для первой разведки. Океан на западе. Низменная равнина у берега имеет высоту 5–20 м, вода там почти не движется. На возвышенности (300–400 м) на склонах видны ручьи и влажный грунт.", "question": "Какой участок исследовать первым, чтобы найти вероятный исток реки? Нажми на участок схемы.", "hint": "Вода начинает путь там, где выше, и там, где её много. Обрати внимание на ручьи.", "explanation": "Истоки чаще лежат на возвышенностях: оттуда вода стекает вниз. Но не каждая возвышенность даёт реку: нужны ещё осадки или родники. Здесь на склонах уже видны ручьи, значит, исток вероятнее всего там.", "extra": false, "complex": false, "correctZone": "upland", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 70, "h": 180, "c": "water"}, {"t": "text", "x": 35, "y": 90, "s": "Океан"}, {"t": "zone", "id": "plain", "label": "Низменная равнина, 5–20 м", "x": 75, "y": 10, "w": 80, "h": 160, "c": "low"}, {"t": "zone", "id": "upland", "label": "Возвышенность, 300–400 м, ручьи на склонах", "x": 160, "y": 10, "w": 135, "h": 160, "c": "hill"}]}}, {"id": "task-003", "sectorId": "sector-01", "type": "analysis", "topic": "water", "title": "Куда потечёт вода", "description": "На схеме отмечены высоты вдоль линии с востока на запад: вершина 400 м, источник 320 м, склон 150 м, берег океана 5 м. Других препятствий нет.", "question": "В каком направлении вероятнее потечёт вода от источника?", "hint": "Вода течёт вниз по уклону поверхности. Сравни высоты по обе стороны от источника.", "explanation": "От источника (320 м) поверхность понижается на запад: 150 м, затем 5 м у океана. Вода течёт вниз по склону, значит, на запад, к океану. На восток поверхность поднимается, туда вода течь не будет.", "extra": false, "complex": true, "options": ["На запад, к океану", "На восток, к вершине 400 м", "Вода останется на месте", "Вверх по склону"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 70, "h": 180, "c": "water"}, {"t": "text", "x": 35, "y": 70, "s": "Океан"}, {"t": "dot", "x": 90, "y": 110, "label": "Берег, 5 м"}, {"t": "dot", "x": 160, "y": 110, "label": "Склон, 150 м"}, {"t": "dot", "x": 225, "y": 110, "label": "Источник, 320 м"}, {"t": "dot", "x": 280, "y": 110, "label": "Вершина, 400 м"}]}}, {"id": "task-004", "sectorId": "sector-01", "type": "identify", "topic": "relief", "title": "Тип рельефа", "description": "Спутник передал описание: «Низкая ровная поверхность вдоль берега океана, высоты не более 50 м».", "question": "Какой форме рельефа соответствует это описание?", "hint": "Ровная, низкая, возле моря.", "explanation": "Низкая ровная поверхность вдоль океана называется приморской (прибрежной) равниной. Горный хребет и вулкан высокие, ледниковый купол встречается там, где холодно.", "extra": true, "complex": false, "options": ["Приморская равнина", "Горный хребет", "Ледниковый купол", "Вулканический конус"], "correctAnswer": 0}, {"id": "task-005", "sectorId": "sector-02", "type": "multiple_choice", "topic": "climate", "title": "Наветренный склон", "description": "С океана на запад хребта постоянно дует ветер (стрелка на схеме). Хребет вытянут с севера на юг.", "question": "Какой склон хребта наветренный, то есть тот, на который набегает ветер?", "hint": "Посмотри, откуда направлена стрелка ветра и какой склон встречает её первым.", "explanation": "Ветер идёт с запада на восток, поэтому первым встречает хребет западный склон — он наветренный. Восточный склон находится «в укрытии» и называется подветренным.", "extra": false, "complex": false, "options": ["Западный", "Восточный", "Оба одновременно", "Ни один"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 40, "h": 180, "c": "water"}, {"t": "text", "x": 20, "y": 150, "s": "Океан"}, {"t": "poly", "pts": "120,170 150,20 180,170", "c": "mount"}, {"t": "arrow", "x1": 10, "y1": 70, "x2": 115, "y2": 70, "label": "Ветер"}, {"t": "text", "x": 100, "y": 135, "s": "западный склон"}, {"t": "text", "x": 205, "y": 135, "s": "восточный склон"}]}}, {"id": "task-006", "sectorId": "sector-02", "type": "map_click", "topic": "climate", "title": "Где больше осадков", "description": "Влажный ветер с океана идёт на восток и встречает хребет (см. схему). Воздух вынужден подниматься по склону.", "question": "На каком участке при этих условиях выпадет больше всего осадков?", "hint": "Поднимаясь, воздух охлаждается, и вода из пара превращается в капли.", "explanation": "Влажный воздух поднимается по наветренному (западному) склону, остывает, пар конденсируется, и выпадают осадки. Поэтому наветренный склон самый влажный.", "extra": false, "complex": false, "correctZone": "ws", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 40, "h": 180, "c": "water"}, {"t": "arrow", "x1": 8, "y1": 90, "x2": 62, "y2": 90, "label": "Ветер"}, {"t": "zone", "id": "ws", "label": "Западный склон", "x": 70, "y": 15, "w": 80, "h": 150, "c": "hill"}, {"t": "zone", "id": "sm", "label": "Гребень", "x": 150, "y": 15, "w": 45, "h": 150, "c": "mount"}, {"t": "zone", "id": "es", "label": "Восточный склон", "x": 195, "y": 15, "w": 95, "h": 150, "c": "hill"}]}}, {"id": "task-007", "sectorId": "sector-02", "type": "analysis", "topic": "water", "title": "Исток рек", "description": "Разведка показала: на вершинах лежит снег; на западном склоне осадков много, на высоте 1500–2000 м из-под снега вытекают ручьи; на восточном предгорье сухо; на низкой прибрежной равнине ручьёв нет.", "question": "Где вероятнее всего начинаются крупные реки массива?", "hint": "Реки начинаются там, где много воды (осадки, снег) и откуда её можно спускать вниз.", "explanation": "Много воды даёт верхняя часть наветренного склона: осадки, снег, ручьи. Оттуда вода стекает вниз и собирается в реки. На сухом восточном предгорье и на равнине воды для истока мало.", "extra": false, "complex": true, "options": ["В верхней части западного склона", "На сухом восточном предгорье", "На прибрежной равнине у океана", "Нигде, реки здесь не возможны"], "correctAnswer": 0}, {"id": "task-008", "sectorId": "sector-02", "type": "identify", "topic": "relief", "title": "Горная система", "description": "Описание с орбиты: «Протяжённая цепочка высоких гор, вытянутых в одну линию, с вершинами выше 3000 м».", "question": "Как называется такая форма рельефа?", "hint": "Цепочка — значит, вытянута в линию.", "explanation": "Протяжённая цепь гор — горный хребет (вместе с соседними — горная система). Котловина — понижение, дельта — равнина в устье реки, атолл — коралловый остров.", "extra": true, "complex": false, "options": ["Горный хребет", "Котловина", "Дельта", "Атолл"], "correctAnswer": 0}, {"id": "task-009", "sectorId": "sector-03", "type": "multiple_choice", "topic": "climate", "title": "Воздух и горы", "description": "Влажный ветер с запада встречает хребет. За хребтом лежит равнина (данные: осадков мало).", "question": "Что происходит с влажным воздухом, когда он поднимается по наветренному склону?", "hint": "Чем выше, тем ниже температура. А при охлаждении пар конденсируется.", "explanation": "Поднимаясь, воздух охлаждается, водяной пар конденсируется в облака и выпадает осадками. К гребню воздух становится суше — он теряет часть влаги.", "extra": false, "complex": false, "options": ["Охлаждается, пар конденсируется, выпадают осадки", "Нагревается и становится ещё влажнее", "Не меняется", "Поворачивает обратно к океану"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "poly", "pts": "90,170 130,40 170,170", "c": "mount"}, {"t": "arrow", "x1": 10, "y1": 100, "x2": 85, "y2": 70, "label": "Влажный воздух"}, {"t": "arrow", "x1": 175, "y1": 70, "x2": 280, "y2": 110, "label": "Сухой воздух"}, {"t": "text", "x": 60, "y": 150, "s": "осадки"}, {"t": "text", "x": 235, "y": 150, "s": "равнина"}]}}, {"id": "task-010", "sectorId": "sector-03", "type": "identify", "topic": "climate", "title": "Название явления", "description": "Описание: «Территория на подветренной стороне гор, где мало осадков, потому что воздух, спускаясь по склону, нагревается и становится суше».", "question": "Как называется это явление?", "hint": "Горы создают «тень» от дождя.", "explanation": "Это дождевая тень. Горы задерживают влагу на наветренной стороне, а за ними воздух нагревается при спуске и осадков почти нет.", "extra": false, "complex": false, "options": ["Дождевая тень", "Ледниковый купол", "Дельта", "Морское течение"], "correctAnswer": 0}, {"id": "task-011", "sectorId": "sector-03", "type": "analysis", "topic": "climate", "title": "Тип природных условий", "description": "Данные по равнине: осадков 250–300 мм в год; средняя температура июля +22 °C, января −5 °C; деревьев нет, преобладают травы; почва плодородная; поверхность ровная.", "question": "Какие природные условия вероятнее всего характерны для Теневой равнины?", "hint": "Мало осадков, но не пустыня: растут травы.", "explanation": "При осадках 250–300 мм деревья расти не могут, но травы растут. Это условия засушливой степи. Влажный лес требует осадков больше 1000 мм, тундра и ледяная пустыня — это холод, а в июле здесь +22 °C.", "extra": false, "complex": true, "options": ["Засушливая степь", "Влажный лес", "Тундра", "Ледяная пустыня"], "correctAnswer": 0}, {"id": "task-012", "sectorId": "sector-03", "type": "map_click", "topic": "climate", "title": "Дождевая тень", "description": "Ветер с запада, хребет посередине (см. схему).", "question": "В какой части схемы вероятнее образуется дождевая тень?", "hint": "Подумай, где воздух сухой и нагревается при спуске.", "explanation": "Дождевая тень образуется за гребнем, на подветренной стороне. Воздух там спускается и нагревается, облаков мало, осадков тоже.", "extra": true, "complex": false, "correctZone": "b", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "arrow", "x1": 5, "y1": 20, "x2": 70, "y2": 20, "label": "Ветер"}, {"t": "zone", "id": "a", "label": "Наветренный склон", "x": 10, "y": 40, "w": 100, "h": 130, "c": "hill"}, {"t": "zone", "id": "m", "label": "Гребень", "x": 110, "y": 40, "w": 40, "h": 130, "c": "mount"}, {"t": "zone", "id": "b", "label": "Подветренная равнина", "x": 150, "y": 40, "w": 140, "h": 130, "c": "dry"}]}}, {"id": "task-013", "sectorId": "sector-04", "type": "identify", "topic": "relief", "title": "Описание формы рельефа", "description": "Описание: «Вытянутое понижение поверхности, по которому вода стекает с возвышенностей к более низким участкам».", "question": "Какой объект описан?", "hint": "Вода течёт по этому понижению.", "explanation": "Это речная долина: вытянутое понижение, по дну которого течёт река. Вулканический конус — возвышенность, ледниковый купол — ледяной покров, желоб — глубокое место в океане.", "extra": false, "complex": false, "options": ["Речная долина", "Вулканический конус", "Ледниковый купол", "Океанический желоб"], "correctAnswer": 0}, {"id": "task-014", "sectorId": "sector-04", "type": "multiple_choice", "topic": "water", "title": "Скорость течения", "description": "Река в долине течёт с севера на юг. В верховье (у гор) уклон русла 40 м на километр, в низовье (у океана) 0,5 м на километр.", "question": "На каком участке течение быстрее?", "hint": "Чем круче уклон, тем быстрее течёт вода.", "explanation": "Скорость течения зависит от уклона. В верховье уклон гораздо больше, значит, там река быстрая и бурная. В низовье уклон мал и течение спокойное.", "extra": false, "complex": false, "options": ["В верховье", "В низовье", "Везде одинаково", "Определить нельзя"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 135, "y": 0, "w": 30, "h": 180, "c": "water"}, {"t": "dot", "x": 150, "y": 25, "label": "Верховье: 40 м/км"}, {"t": "dot", "x": 150, "y": 155, "label": "Низовье: 0,5 м/км"}, {"t": "arrow", "x1": 150, "y1": 40, "x2": 150, "y2": 140, "label": "течёт на юг"}]}}, {"id": "task-015", "sectorId": "sector-04", "type": "map_click", "topic": "water", "title": "Спокойное русло", "description": "По долине течёт река с севера на юг. Данные: в верхней части ущелье шириной 5–20 м; в средней части русло 80 м; в нижней части русло 300 м, уклон малый.", "question": "Где вероятнее самое широкое русло и самое спокойное течение?", "hint": "К устью река собирает притоки, а уклон уменьшается.", "explanation": "К нижнему течению в реку впадают притоки, воды становится больше, русло расширяется, а уклон уменьшается, поэтому течение спокойнее.", "extra": false, "complex": false, "correctZone": "low", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "zone", "id": "up", "label": "Верховье: ущелье 5–20 м", "x": 40, "y": 8, "w": 220, "h": 50, "c": "mount"}, {"t": "zone", "id": "mid", "label": "Среднее течение: 80 м", "x": 40, "y": 62, "w": 220, "h": 50, "c": "hill"}, {"t": "zone", "id": "low", "label": "Нижнее течение: 300 м", "x": 40, "y": 116, "w": 220, "h": 56, "c": "low"}]}}, {"id": "task-016", "sectorId": "sector-04", "type": "analysis", "topic": "water", "title": "Больше воды в низовье", "description": "Измерения: расход воды у верховья 20 м³/с, на среднем участке 90 м³/с, у устья 400 м³/с. На всём протяжении река принимает несколько притоков с гор. Осадков в долине немного.", "question": "Чем вероятнее всего объясняется рост расхода воды вниз по течению?", "hint": "Подумай, что впадает в реку по пути.", "explanation": "Расход растёт потому, что в реку впадают притоки со всего водосбора. Осадков в долине мало, поэтому дело не в них.", "extra": true, "complex": false, "options": ["В реку впадают притоки", "Вода поднимается из океана", "Река получает воду от Солнца", "Это ошибка приборов"], "correctAnswer": 0}, {"id": "task-017", "sectorId": "sector-05", "type": "multiple_choice", "topic": "water", "title": "Куда уходит вода", "description": "Котловина окружена возвышенностями 400–600 м. Внутри самое низкое место лежит на высоте 80 м. Реки текут от краёв к центру, выхода из котловины нет.", "question": "Что произойдёт с водой рек, текущих в котловину?", "hint": "Вода течёт вниз. А выхода из понижения нет.", "explanation": "Вода стекает в самое низкое место и накапливается там, образуя озеро. Так как выхода нет, избыток убывает только за счёт испарения.", "extra": false, "complex": false, "options": ["Соберётся в центре и образует озеро", "Уйдёт в океан через горы", "Поднимется на вершины", "Исчезнет без следа сразу"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "hill"}, {"t": "zone", "id": "c", "label": "Центр, 80 м", "x": 100, "y": 60, "w": 100, "h": 60, "c": "low"}, {"t": "text", "x": 150, "y": 25, "s": "Хребты 400–600 м"}, {"t": "text", "x": 150, "y": 165, "s": "Хребты 400–600 м"}, {"t": "arrow", "x1": 60, "y1": 90, "x2": 98, "y2": 90, "label": ""}, {"t": "arrow", "x1": 240, "y1": 90, "x2": 202, "y2": 90, "label": ""}, {"t": "arrow", "x1": 150, "y1": 35, "x2": 150, "y2": 58, "label": ""}, {"t": "arrow", "x1": 150, "y1": 150, "x2": 150, "y2": 122, "label": ""}]}}, {"id": "task-018", "sectorId": "sector-05", "type": "identify", "topic": "relief", "title": "Тип понижения", "description": "Описание: «Замкнутое понижение, окружённое возвышенностями; воды стекают внутрь, стока в океан нет».", "question": "Как называется такая форма рельефа?", "hint": "Нет стока в океан — значит, «бессточная».", "explanation": "Это бессточная котловина. Дельта образуется в устье реки, вулканический конус — возвышенность, хребет — цепь гор.", "extra": false, "complex": false, "options": ["Бессточная котловина", "Дельта", "Вулканический конус", "Горный хребет"], "correctAnswer": 0}, {"id": "task-019", "sectorId": "sector-05", "type": "analysis", "topic": "water", "title": "Солёное озеро", "description": "В котловине лежит озеро. Реки приносят в него растворённые соли, но стока из озера нет. Климат жаркий, с сильным испарением.", "question": "Какой станет вода в озере со временем?", "hint": "Вода испаряется, а соли остаются.", "explanation": "Вода испаряется, а растворённые соли остаются в озере и накапливаются. Со временем вода становится солёной. Озеро без стока — солёное.", "extra": false, "complex": true, "options": ["Солёной", "Всё более пресной", "Останется такой же, как была", "Озеро исчезнет вместе с солью"], "correctAnswer": 0}, {"id": "task-020", "sectorId": "sector-05", "type": "map_click", "topic": "relief", "title": "Самая низкая точка", "description": "На схеме показаны абсолютные высоты частей котловины.", "question": "Где находится самая низкая часть котловины, куда стекает вода?", "hint": "Вода собирается там, где высота наименьшая.", "explanation": "Центральная часть (80 м) ниже всех остальных, поэтому именно туда стекает вода и там образуется озеро.", "extra": true, "complex": false, "correctZone": "c", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "zone", "id": "n", "label": "Северный борт, 520 м", "x": 70, "y": 8, "w": 160, "h": 40, "c": "mount"}, {"t": "zone", "id": "w", "label": "Западная часть, 260 м", "x": 8, "y": 52, "w": 90, "h": 76, "c": "hill"}, {"t": "zone", "id": "c", "label": "Центр, 80 м", "x": 102, "y": 52, "w": 96, "h": 76, "c": "low"}, {"t": "zone", "id": "e", "label": "Восточная часть, 300 м", "x": 202, "y": 52, "w": 90, "h": 76, "c": "hill"}, {"t": "zone", "id": "s", "label": "Южный борт, 480 м", "x": 70, "y": 132, "w": 160, "h": 40, "c": "mount"}]}}, {"id": "task-021", "sectorId": "sector-06", "type": "multiple_choice", "topic": "climate", "title": "Откуда лес", "description": "Ветры с океана приходят на наветренные предгорья. Осадков 1800 мм в год, средняя годовая температура +10 °C. Рельеф холмистый, почва развитая.", "question": "Почему на этих склонах вырос густой лес?", "hint": "Лесу нужна влага и тепло.", "explanation": "Много осадков и умеренная температура создают условия для леса. На сухих склонах без достатка воды лес не вырос бы.", "extra": false, "complex": false, "options": ["Много осадков и умеренная температура", "Мало осадков и сильный мороз", "Здесь нет ветров", "Деревья растут только на равнине"], "correctAnswer": 0}, {"id": "task-022", "sectorId": "sector-06", "type": "analysis", "topic": "climate", "title": "Смена растительности", "description": "От подножия до вершины высота растёт на 3 км. Температура с высотой падает примерно на 6 °C на каждый километр. У подножия лес.", "question": "Что вероятнее всего произойдёт с растительностью при подъёме в гору?", "hint": "Чем выше, тем холоднее.", "explanation": "С высотой холоднее. Лес сменяется лугами, а выше — голыми скалами и снегом. Это высотная поясность.", "extra": false, "complex": true, "options": ["Лес сменится лугами, затем голыми скалами и снегом", "Лес станет гуще", "Появятся пальмы", "Ничего не изменится"], "correctAnswer": 0}, {"id": "task-023", "sectorId": "sector-06", "type": "map_click", "topic": "climate", "title": "Где лес гуще", "description": "Ветер дует с океана на запад хребта. Осадки: наветренные предгорья 1800 мм, подветренное предгорье 300 мм, вершина — снег.", "question": "Где вероятнее всего растёт самый густой лес?", "hint": "Лес любит влагу.", "explanation": "Наветренные предгорья получают больше всего осадков, поэтому лес там самый густой. На подветренной стороне суше, а на вершине холодно.", "extra": false, "complex": false, "correctZone": "ww", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 40, "h": 180, "c": "water"}, {"t": "arrow", "x1": 8, "y1": 90, "x2": 62, "y2": 90, "label": "Ветер"}, {"t": "zone", "id": "ww", "label": "Наветренные предгорья, 1800 мм", "x": 70, "y": 15, "w": 80, "h": 150, "c": "forest"}, {"t": "zone", "id": "pk", "label": "Вершина, снег", "x": 150, "y": 15, "w": 50, "h": 150, "c": "ice"}, {"t": "zone", "id": "lw", "label": "Подветренное предгорье, 300 мм", "x": 200, "y": 15, "w": 90, "h": 150, "c": "dry"}]}}, {"id": "task-024", "sectorId": "sector-06", "type": "identify", "topic": "climate", "title": "Закономерность", "description": "Описание: «Смена природных поясов по мере подъёма в горы из-за понижения температуры».", "question": "Как называется эта закономерность?", "hint": "Речь о высоте.", "explanation": "Это высотная поясность. Широтная зональность — смена зон от экватора к полюсам.", "extra": true, "complex": false, "options": ["Высотная поясность", "Широтная зональность", "Дождевая тень", "Морское течение"], "correctAnswer": 0}, {"id": "task-025", "sectorId": "sector-07", "type": "multiple_choice", "topic": "relief", "title": "Цепочка вулканов", "description": "Пять вулканов расположены в одну линию длиной 200 км. Рядом по поверхности видна трещина, вдоль которой земля смещена.", "question": "Чем вероятнее всего объясняется расположение вулканов в линию?", "hint": "Подумай о трещине в земной коре.", "explanation": "Вулканы часто возникают вдоль разломов земной коры, где магма поднимается к поверхности. Поэтому они выстроены цепочкой.", "extra": false, "complex": false, "options": ["Они расположены вдоль линии разлома", "Их поставили течения", "Они возникли от осадков", "Это случайность без причины"], "correctAnswer": 0}, {"id": "task-026", "sectorId": "sector-07", "type": "identify", "topic": "relief", "title": "Форма рельефа", "description": "Описание: «Гора конической формы, из жерла которой извергаются лава, пепел и газы».", "question": "Что описано?", "hint": "Из жерла идёт лава.", "explanation": "Это вулкан (вулканический конус). Дельта, ледниковый купол и барханы имеют иное происхождение.", "extra": false, "complex": false, "options": ["Вулкан", "Ледниковый купол", "Речная долина", "Бархан"], "correctAnswer": 0}, {"id": "task-027", "sectorId": "sector-07", "type": "analysis", "topic": "relief", "title": "Плодородная почва", "description": "Вокруг вулканов растительность гуще, чем на соседней равнине той же высоты. Климат одинаков. Вокруг лежат слои старого пепла.", "question": "Наиболее вероятное объяснение?", "hint": "Что содержится в пепле?", "explanation": "Вулканический пепел содержит много минеральных веществ, и почвы на нём плодородные. Это объясняет густую растительность.", "extra": false, "complex": true, "options": ["Пепел делает почву плодородной", "Вулканы приносят дожди из океана", "Лава охлаждает воздух", "Растения питаются газами"], "correctAnswer": 0}, {"id": "task-028", "sectorId": "sector-07", "type": "map_click", "topic": "relief", "title": "Где новый вулкан", "description": "Вулканы расположены вдоль линии разлома (на схеме линия идёт с северо-запада на юго-восток).", "question": "Где вероятнее появление нового вулкана?", "hint": "Ищи вдоль разлома.", "explanation": "Магма поднимается вдоль разлома, поэтому новый вулкан вероятнее всего появится на продолжении линии разлома.", "extra": true, "complex": false, "correctZone": "line", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "poly", "pts": "20,30 280,150 285,160 15,40", "c": "lava"}, {"t": "zone", "id": "line", "label": "Продолжение линии разлома", "x": 205, "y": 108, "w": 85, "h": 60, "c": "lava"}, {"t": "zone", "id": "side", "label": "Район в 100 км в стороне", "x": 20, "y": 110, "w": 100, "h": 60, "c": "low"}, {"t": "zone", "id": "coast", "label": "Побережье океана", "x": 150, "y": 8, "w": 140, "h": 50, "c": "water"}]}}, {"id": "task-029", "sectorId": "sector-08", "type": "multiple_choice", "topic": "climate", "title": "Климат острова", "description": "На острове: средняя температура июля +16 °C, января +6 °C. На материке в той же широте вдали от океана: июля +24 °C, января −12 °C.", "question": "Почему на острове перепады температуры между зимой и летом меньше?", "hint": "Вода нагревается и остывает медленно.", "explanation": "Океан медленно нагревается и остывает, поэтому смягчает климат: зима тёплая, лето прохладное.", "extra": false, "complex": false, "options": ["Океан смягчает климат", "Остров ближе к Солнцу", "На острове нет ветра", "Остров выше над уровнем моря"], "correctAnswer": 0}, {"id": "task-030", "sectorId": "sector-08", "type": "analysis", "topic": "climate", "title": "Осадки на острове", "description": "Осадки на острове 1500 мм, во внутренних районах материка в тех же широтах 400 мм. Остров со всех сторон окружён тёплой водой океана.", "question": "Какое объяснение вероятнее всего?", "hint": "Откуда берётся влага для осадков?", "explanation": "Над тёплым океаном воздух насыщается влагой, и на острове осадков много. Внутри материка влажные ветры дойдут не всегда.", "extra": false, "complex": true, "options": ["Воздух над океаном приносит много влаги", "Остров лежит в дождевой тени", "Остров очень сухой", "Осадки выпадают только на материке"], "correctAnswer": 0}, {"id": "task-031", "sectorId": "sector-08", "type": "map_click", "topic": "relief", "title": "Высшая точка", "description": "На схеме острова показаны высоты участков.", "question": "Где находится самая высокая часть острова?", "hint": "Сравни числа.", "explanation": "Центральный холм (600 м) выше остальных участков, поэтому это высшая точка острова.", "extra": false, "complex": false, "correctZone": "c", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "water"}, {"t": "zone", "id": "n", "label": "Север, 20 м", "x": 90, "y": 12, "w": 120, "h": 40, "c": "low"}, {"t": "zone", "id": "w", "label": "Запад, 180 м", "x": 30, "y": 56, "w": 70, "h": 66, "c": "hill"}, {"t": "zone", "id": "c", "label": "Центр, 600 м", "x": 104, "y": 56, "w": 92, "h": 66, "c": "mount"}, {"t": "zone", "id": "e", "label": "Восток, 200 м", "x": 200, "y": 56, "w": 70, "h": 66, "c": "hill"}, {"t": "zone", "id": "s", "label": "Юг, 15 м", "x": 90, "y": 126, "w": 120, "h": 40, "c": "low"}]}}, {"id": "task-032", "sectorId": "sector-08", "type": "identify", "topic": "climate", "title": "Тип климата", "description": "Описание: «Климат с мягкой зимой, прохладным летом, малыми колебаниями температуры и обилием осадков, формируется под влиянием океана».", "question": "Как называется такой климат?", "hint": "Речь об океане.", "explanation": "Это морской климат. Континентальный климат формируется вдали от океана и имеет большие перепады.", "extra": true, "complex": false, "options": ["Морской", "Резко континентальный", "Пустынный", "Полярный"], "correctAnswer": 0}, {"id": "task-033", "sectorId": "sector-09", "type": "multiple_choice", "topic": "climate", "title": "Холод на севере", "description": "В полдень Солнце стоит над горизонтом очень низко. Лучи падают на поверхность под малым углом и скользят по ней.", "question": "Почему в полярной области холодно?", "hint": "Чем меньше угол падения лучей, тем меньше тепла получает поверхность.", "explanation": "При малом угле падения одинаковый поток лучей распределяется по большей площади и поверхность получает меньше тепла. Поэтому на севере холодно.", "extra": false, "complex": false, "options": ["Лучи падают под малым углом и дают мало тепла", "Солнце находится ближе к планете", "Там нет атмосферы", "Там всегда дуют тёплые ветры"], "correctAnswer": 0}, {"id": "task-034", "sectorId": "sector-09", "type": "identify", "topic": "relief", "title": "Ледяной объект", "description": "Описание: «Мощная масса льда, образовавшаяся из спрессованного снега, которая медленно движется под действием силы тяжести».", "question": "Что описано?", "hint": "Лёд движется очень медленно.", "explanation": "Это ледник. Дельта — равнина в устье, бархан — песчаный холм, атолл — коралловый остров.", "extra": false, "complex": false, "options": ["Ледник", "Дельта", "Бархан", "Атолл"], "correctAnswer": 0}, {"id": "task-035", "sectorId": "sector-09", "type": "analysis", "topic": "climate", "title": "Летнее Солнце и холод", "description": "В июне Солнце здесь не заходит сутками, но температура остаётся около 0 °C. Поверхность покрыта снегом.", "question": "Чем вероятнее всего объясняется низкая температура несмотря на круглосуточное Солнце?", "hint": "Подумай про угол лучей и белый снег.", "explanation": "Лучи падают под малым углом, а белый снег отражает большую часть света; тепло уходит ещё и на таяние льда. Поэтому нагрев слабый.", "extra": false, "complex": true, "options": ["Лучи падают под малым углом, снег отражает свет", "Солнце светит слабее, чем в других местах", "Там нет воздуха", "Лёд нагревает воздух"], "correctAnswer": 0}, {"id": "task-036", "sectorId": "sector-09", "type": "map_click", "topic": "climate", "title": "Где ледяной купол", "description": "Данные: центральное плато 1800 м, средняя температура −20 °C, снег не тает; прибрежная низина 40 м, летом +2 °C; южные предгорья 600 м, летом +5 °C.", "question": "Где вероятнее всего накапливается ледяной купол?", "hint": "Лёд копится там, где снег не успевает растаять.", "explanation": "На плато выше и холоднее всего, снег не тает и со временем превращается в лёд. Там и образуется ледяной купол.", "extra": true, "complex": false, "correctZone": "plateau", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "zone", "id": "plateau", "label": "Плато, 1800 м, −20 °C", "x": 90, "y": 15, "w": 120, "h": 70, "c": "ice"}, {"t": "zone", "id": "coast", "label": "Низина, 40 м, +2 °C", "x": 10, "y": 100, "w": 130, "h": 70, "c": "low"}, {"t": "zone", "id": "south", "label": "Предгорья, 600 м, +5 °C", "x": 160, "y": 100, "w": 130, "h": 70, "c": "hill"}]}}, {"id": "task-037", "sectorId": "sector-10", "type": "multiple_choice", "topic": "climate", "title": "Причины засушливости", "description": "Пустыня лежит в 1500 км от океана, за двумя хребтами. Осадков менее 100 мм в год.", "question": "Что вероятнее всего объясняет малое количество осадков?", "hint": "Ветры теряют влагу по пути.", "explanation": "Влажные ветры отдают влагу над горами, а до глубины материка доходят сухими. Так формируются пустыни в глубине суши.", "extra": false, "complex": false, "options": ["Воздух теряет влагу над горами и идёт далеко от океана", "Пустыня расположена на берегу океана", "Там много рек", "Пустыня лежит на наветренной стороне гор"], "correctAnswer": 0}, {"id": "task-038", "sectorId": "sector-10", "type": "analysis", "topic": "climate", "title": "Суточные перепады", "description": "Днём в пустыне +38 °C, ночью +5 °C. Воздух сухой, небо ясное, облаков нет, растительности почти нет.", "question": "Чем объясняются большие суточные перепады температуры?", "hint": "Облака и влага удерживают тепло.", "explanation": "Днём поверхность сильно нагревается. Ночью без облаков и влаги тепло быстро уходит, поэтому перепады большие.", "extra": false, "complex": true, "options": ["Сухой воздух и ясное небо слабо удерживают тепло", "Ночью Солнце ближе к планете", "Ветер нагревает воздух днём", "Океан нагревает пустыню"], "correctAnswer": 0}, {"id": "task-039", "sectorId": "sector-10", "type": "identify", "topic": "water", "title": "Живой островок", "description": "Описание: «Участок с водой и растительностью среди пустыни, где грунтовые воды выходят близко к поверхности».", "question": "Как называется такой участок?", "hint": "Ищи слово, связанное с пустыней.", "explanation": "Это оазис. Дельта находится в устье реки, фьорд — залив, лагуна — мелководье у берега.", "extra": false, "complex": false, "options": ["Оазис", "Дельта", "Фьорд", "Лагуна"], "correctAnswer": 0}, {"id": "task-040", "sectorId": "sector-10", "type": "map_click", "topic": "water", "title": "Где искать оазис", "description": "Грунтовые воды на схеме: на песчаной гряде — глубже 80 м; на каменистом плато — глубже 50 м; в низине у подножия хребта — 2 м.", "question": "Где вероятнее появление оазиса?", "hint": "Растениям нужна вода близко к поверхности.", "explanation": "В низине вода залегает на глубине 2 м — корням растений она доступна. Там вероятнее всего будет оазис.", "extra": true, "complex": false, "correctZone": "low", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "zone", "id": "sand", "label": "Песчаная гряда, вода глубже 80 м", "x": 10, "y": 15, "w": 130, "h": 70, "c": "dry"}, {"t": "zone", "id": "rock", "label": "Плато, вода глубже 50 м", "x": 160, "y": 15, "w": 130, "h": 70, "c": "dry"}, {"t": "zone", "id": "low", "label": "Низина у хребта, вода на 2 м", "x": 60, "y": 100, "w": 180, "h": 70, "c": "low"}]}}, {"id": "task-041", "sectorId": "sector-11", "type": "identify", "topic": "water", "title": "Форма рельефа в устье", "description": "Описание: «Низменная равнина в устье реки, где русло разветвляется на множество рукавов».", "question": "Что описано?", "hint": "Это место, где река впадает в океан.", "explanation": "Это дельта. Рукава образуются, потому что река откладывает наносы и раздваивается.", "extra": false, "complex": false, "options": ["Дельта", "Горный хребет", "Ледниковый купол", "Вулканический конус"], "correctAnswer": 0}, {"id": "task-042", "sectorId": "sector-11", "type": "multiple_choice", "topic": "water", "title": "Наносы", "description": "Река несёт ил и песок. В устье она впадает в океан, и скорость течения резко падает.", "question": "Почему река откладывает наносы в устье?", "hint": "Быстрый поток может нести больше, чем медленный.", "explanation": "Когда скорость течения падает, вода уже не может нести столько ила и песка и отпускает их на дно. Наносы накапливаются и образуют дельту.", "extra": false, "complex": false, "options": ["Скорость течения падает, и вода теряет силу нести наносы", "Скорость течения растёт", "В океане нет воды", "Наносы тяжелеют от солнца"], "correctAnswer": 0}, {"id": "task-043", "sectorId": "sector-11", "type": "map_click", "topic": "water", "title": "Где растёт суша", "description": "Река впадает в океан несколькими рукавами. Рукава несут ил. В устье течение замедляется, в верховье остаётся быстрым.", "question": "Где вероятнее всего будет расти новая суша за счёт наносов?", "hint": "Наносы оседают там, где течение замедляется.", "explanation": "Новая суша растёт там, где рукава впадают в океан: течение слабое, наносы оседают, образуются острова и отмели.", "extra": false, "complex": false, "correctZone": "mouth", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 120, "w": 300, "h": 60, "c": "water"}, {"t": "zone", "id": "up", "label": "Верховье, течение быстрое", "x": 40, "y": 8, "w": 220, "h": 40, "c": "hill"}, {"t": "zone", "id": "mid", "label": "Среднее течение", "x": 40, "y": 52, "w": 220, "h": 40, "c": "low"}, {"t": "zone", "id": "mouth", "label": "Устье, течение медленное", "x": 40, "y": 96, "w": 220, "h": 70, "c": "low"}]}}, {"id": "task-044", "sectorId": "sector-11", "type": "analysis", "topic": "water", "title": "Плодородие дельты", "description": "Почвы дельты — ил, принесённый рекой с гор и равнин. В нём много органических остатков и минеральных веществ.", "question": "Почему почвы дельты плодородны?", "hint": "Что приносит река?", "explanation": "Река приносит ил с минеральными и органическими веществами, и почва в дельте плодородная.", "extra": true, "complex": false, "options": ["Река приносит питательный ил", "Почва состоит из чистого песка", "Океан удобряет её солью", "Здесь нет растений"], "correctAnswer": 0}, {"id": "task-045", "sectorId": "sector-12", "type": "multiple_choice", "topic": "climate", "title": "Тёплая вода", "description": "Течение идёт вдоль западного берега с юга на север. Температура воды в течении +22 °C, вокруг +12 °C. Чем южнее, тем теплее (полярная область на севере).", "question": "К чему приведёт движение тёплой воды вдоль берега на север?", "hint": "Тёплая вода нагревает воздух над ней.", "explanation": "Воздух над тёплым течением нагревается и приносит тепло на берег: зима там мягче.", "extra": false, "complex": false, "options": ["Прибрежный воздух теплеет, зимы мягче", "Берег станет холоднее", "Течение остановит ветры", "Ничего не изменится"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 120, "h": 180, "c": "water"}, {"t": "arrow", "x1": 60, "y1": 165, "x2": 60, "y2": 20, "label": "Тёплое течение"}, {"t": "text", "x": 200, "y": 90, "s": "Суша"}]}}, {"id": "task-046", "sectorId": "sector-12", "type": "analysis", "topic": "climate", "title": "Зима у берега", "description": "В январе на побережье у течения +5 °C, в глубине суши на той же широте −10 °C. Побережье не защищено горами, ветры дуют с океана.", "question": "Как объяснить разницу?", "hint": "Ветры идут с океана, вода тёплая.", "explanation": "Ветры с океана несут тепло течения на берег, поэтому зимой там теплее. В глубине суши воздух не получает тепла от океана.", "extra": false, "complex": true, "options": ["Тёплое течение и океанический ветер смягчают зиму на побережье", "Побережье ближе к полюсу", "Глубь суши получает тепло от течения", "Побережье выше над уровнем моря"], "correctAnswer": 0}, {"id": "task-047", "sectorId": "sector-12", "type": "map_click", "topic": "climate", "title": "Где тепло от течения", "description": "Течение идёт вдоль западного берега. Ветры дуют с океана на сушу.", "question": "Какой участок получает больше всего тепла от течения?", "hint": "Тепло передаётся ветром с океана.", "explanation": "Побережье рядом с течением получает тепло напрямую от воды и воздуха над ней. Чем дальше от океана, тем слабее влияние.", "extra": false, "complex": false, "correctZone": "coast", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "land"}, {"t": "rect", "x": 0, "y": 0, "w": 90, "h": 180, "c": "water"}, {"t": "arrow", "x1": 40, "y1": 165, "x2": 40, "y2": 20, "label": "Течение"}, {"t": "zone", "id": "coast", "label": "Побережье у течения", "x": 95, "y": 15, "w": 70, "h": 150, "c": "low"}, {"t": "zone", "id": "inland", "label": "Глубь суши, 1000 км от моря", "x": 170, "y": 15, "w": 120, "h": 150, "c": "dry"}]}}, {"id": "task-048", "sectorId": "sector-12", "type": "identify", "topic": "water", "title": "Движение океана", "description": "Описание: «Постоянное перемещение огромных масс воды в океане в определённом направлении».", "question": "Как называется это явление?", "hint": "Вода «течёт» в океане.", "explanation": "Это морское течение. Приливы — это ежедневные подъёмы уровня воды, а цунами — гигантские волны от подводных землетрясений.", "extra": true, "complex": false, "options": ["Морское течение", "Прилив", "Цунами", "Ледниковый покров"], "correctAnswer": 0}], "discoveries": [{"id": "discovery-001", "name": "Направление речного стока", "category": "Вода", "short": "Вода течёт с возвышенностей к океану.", "long": "Из центра приморской равнины вода уходит на запад, к океану. Значит, речная сеть материка начинается в глубине суши.", "sectors": ["sector-01"], "condition": {"type": "sectorExplored", "sector": "sector-01"}}, {"id": "discovery-002", "name": "Горный хребет влияет на климат", "category": "Климат", "short": "Западный склон хребта получает много осадков.", "long": "Влажные ветры с океана поднимаются по склону, остывают и отдают влагу. Это даёт воду для рек и влияет на климат всего материка.", "sectors": ["sector-02"], "condition": {"type": "sectorExplored", "sector": "sector-02"}}, {"id": "discovery-003", "name": "Дождевая тень", "category": "Климат", "short": "За хребтом выпадает мало осадков.", "long": "Воздух теряет влагу на наветренном склоне, а затем нагревается при спуске. За горами образуется засушливая равнина.", "sectors": ["sector-03"], "condition": {"type": "sectorExplored", "sector": "sector-03"}}, {"id": "discovery-004", "name": "Серебряная река", "category": "Вода", "short": "Река течёт с гор на юг к океану.", "long": "Верховья быстрые, низовье спокойное. Река собирает притоки, и расход воды растёт к устью.", "sectors": ["sector-04"], "condition": {"type": "sectorExplored", "sector": "sector-04"}}, {"id": "discovery-005", "name": "Бессточный бассейн", "category": "Вода", "short": "В котловине вода не уходит к океану.", "long": "Реки собираются в озере, вода испаряется, а соли остаются. Поэтому озеро солёное.", "sectors": ["sector-05"], "condition": {"type": "sectorExplored", "sector": "sector-05"}}, {"id": "discovery-006", "name": "Высотная поясность", "category": "Природные зоны", "short": "С высотой лес сменяется лугами и скалами.", "long": "Температура падает с высотой, поэтому растительность меняется по поясам.", "sectors": ["sector-06"], "condition": {"type": "sectorExplored", "sector": "sector-06"}}, {"id": "discovery-007", "name": "Вулканическая цепь", "category": "Рельеф", "short": "Вулканы выстроены вдоль разлома.", "long": "Магма поднимается вдоль трещины в земной коре. Пепел делает почвы плодородными.", "sectors": ["sector-07"], "condition": {"type": "sectorExplored", "sector": "sector-07"}}, {"id": "discovery-008", "name": "Морской климат острова", "category": "Климат", "short": "Океан смягчает климат острова.", "long": "Вода нагревается и остывает медленно, поэтому зимы мягкие, а лето прохладное.", "sectors": ["sector-08"], "condition": {"type": "sectorExplored", "sector": "sector-08"}}, {"id": "discovery-009", "name": "Полярный климат", "category": "Климат", "short": "Низкое Солнце и снег создают холод.", "long": "Лучи падают под малым углом, снег отражает свет. Лёд накапливается на плато.", "sectors": ["sector-09"], "condition": {"type": "sectorExplored", "sector": "sector-09"}}, {"id": "discovery-010", "name": "Пустыня глубины материка", "category": "Природные зоны", "short": "Далеко от океана и за горами осадков почти нет.", "long": "Сухой воздух и ясное небо дают большие суточные перепады. Жизнь возможна у грунтовых вод.", "sectors": ["sector-10"], "condition": {"type": "sectorExplored", "sector": "sector-10"}}, {"id": "discovery-011", "name": "Дельта реки", "category": "Вода", "short": "В устье река откладывает наносы и ветвится.", "long": "Течение замедляется, ил оседает, суша растёт. Почвы дельты плодородны.", "sectors": ["sector-11"], "condition": {"type": "sectorExplored", "sector": "sector-11"}}, {"id": "discovery-012", "name": "Тёплое течение", "category": "Океан", "short": "Тёплая вода смягчает климат побережья.", "long": "Течение несёт тепло с юга на север. Ветры с океана приносят его на берег.", "sectors": ["sector-12"], "condition": {"type": "sectorExplored", "sector": "sector-12"}}], "events": {"gameStart": "Экспедиция началась. Приборы фиксируют небольшой участок берега.", "sectorDiscovered": "Обнаружена территория: «{name}».", "sectorExplored": "Исследован сектор «{name}». {journal}", "sectorFull": "Сектор «{name}» изучен полностью.", "discovery": "Открытие: «{name}».", "achievement": "Достижение: «{name}».", "taskDone": "Выполнено задание «{title}»."}, "chapter2": {"chapter": {"id": 2, "title": "Глава 2. Земля", "shortTitle": "Глава 2", "grade": "7 класс", "startSector": "sector-13", "requiresChapter": null, "mission": "Миссия: составить атлас закономерностей Земли — понять, как устроена географическая оболочка, чем различаются материки и как человек влияет на природу.", "knownFacts": ["Законы природы на Земле те же, что на планете X-01: вода течёт вниз, горы влияют на осадки, климат зависит от условий местности.", "Север на схемах вверху, восток справа. Карта упрощена: материки и океаны показаны схематично, масштаб не соблюдается."], "intro": {"title": "Глава 2. Проверка на Земле", "paragraphs": ["Отчёт об экспедиции на планету X-01 принят. Научный совет делает вывод: законы природы одинаковы везде, значит, их можно проверить на планете, которую мы знаем лучше всего, — на Земле.", "Орбитальный сканер выводит схему Земли: материки, океаны и зоны, где проявляются главные закономерности. Карта упрощена, но все факты настоящие.", "Ваша задача — составить атлас закономерностей Земли: от строения географической оболочки до жизни людей на разных материках. Можно ошибаться, читать подсказки и пробовать снова."], "button": "Начать главу 2"}, "finale": {"title": "Земля исследована", "paragraphs": ["Все 14 зон Большой карты Земли исследованы. Закономерности, найденные на планете X-01, подтвердились: климат зависит от широты, ветров, течений и рельефа; границы плит определяют, где поднимаются горы и действуют вулканы; природа, население и хозяйство каждого материка связаны между собой.", "Человек не только зависит от природы, но и меняет её, поэтому главная задача — беречь географическую оболочку вместе."]}, "map": {"mapWidth": 1100, "mapHeight": 700, "caption": "Земля · схема орбитального сканирования (масштаб не соблюдается)", "oceanLabel": null, "ariaLabel": "Большая карта Земли", "compass": [70, 45], "captionPos": [150, 30], "routes": false}}, "sectors": [{"id": "sector-13", "name": "Географическая оболочка", "type": "shell", "chapter": 2, "description": "Орбитальный сканер выделил тонкий слой, где соприкасаются суша, вода, воздух и живые организмы. Изменение в одном месте отзывается в другом. Нужно понять, по каким законам устроен этот слой.", "geo": "Единая оболочка Земли: литосфера, гидросфера, атмосфера и биосфера связаны; природные зоны сменяются от экватора к полюсам.", "requires": [], "taskIds": ["task-049", "task-050", "task-051", "task-052"], "discoveries": ["discovery-013"], "poly": "509,395 502,450 472,480 437,485 407,451 403,395 414,347 436,300 472,313 499,344", "center": [455, 395], "journal": "Исследована «Географическая оболочка». Её компоненты связаны (целостность), природа меняется от экватора к полюсам (зональность) и в горах с высотой (высотная поясность), а многие процессы повторяются (ритмичность)."}, {"id": "sector-14", "name": "Огненное кольцо", "type": "litho", "chapter": 2, "description": "Вдоль побережий крупного океана сканер фиксирует цепочки вулканов и частые подземные толчки. Внутри материков те же приборы почти ничего не регистрируют. Нужно объяснить, где и почему рельеф «живёт».", "geo": "Границы литосферных плит: здесь горы, вулканы, глубоководные жёлоба и землетрясения.", "requires": ["sector-13"], "taskIds": ["task-053", "task-054", "task-055", "task-056"], "discoveries": ["discovery-014"], "poly": "172,150 159,197 120,226 69,229 31,197 12,150 41,111 72,79 121,71 158,104", "center": [95, 150], "journal": "Исследовано «Огненное кольцо». Литосферные плиты медленно движутся: на их границах возникают горы, вулканы и землетрясения, а в центре плит лежат спокойные платформы с полезными ископаемыми."}, {"id": "sector-15", "name": "Ветры и воздушные массы", "type": "atmo", "chapter": 2, "description": "Над океанами и сушей тянутся постоянные потоки воздуха, а в одном регионе ветер дважды в год меняет направление. Сканер фиксирует разницу давления между поясами.", "geo": "Пояса давления, пассаты, западные ветры и муссоны; воздушные массы разных типов.", "requires": ["sector-13"], "taskIds": ["task-057", "task-058", "task-059", "task-060"], "discoveries": ["discovery-015"], "poly": "808,455 797,497 776,532 746,522 719,501 712,455 724,414 745,381 774,389 800,410", "center": [760, 455], "journal": "Исследованы «Ветры и воздушные массы». Ветер дует из области высокого давления в область низкого, так возникают пассаты, западные ветры и муссоны."}, {"id": "sector-16", "name": "Климатические пояса", "type": "climate", "chapter": 2, "description": "Данные метеостанций из разных частей Земли сведены в таблицы и графики. По ним нужно определить типы климата и понять, что на них влияет.", "geo": "Климат определяют широта, течения, циркуляция атмосферы, рельеф и подстилающая поверхность.", "requires": ["sector-15"], "taskIds": ["task-061", "task-062", "task-063", "task-064"], "discoveries": ["discovery-016"], "poly": "1079,625 1060,653 1012,668 953,677 917,651 890,625 901,593 959,582 1015,577 1064,595", "center": [985, 625], "journal": "Исследованы «Климатические пояса». Климат определяют климатообразующие факторы, а описать его помогает климатограмма."}, {"id": "sector-17", "name": "Мировой океан", "type": "ocean_world", "chapter": 2, "description": "Океаны занимают большую часть поверхности. Спутник измеряет температуру и солёность воды и отслеживает потоки, которые переносят тепло между широтами.", "geo": "Четыре океана, тёплые и холодные течения, солёность, льды, жизнь в океане.", "requires": ["sector-15"], "taskIds": ["task-065", "task-066", "task-067", "task-068"], "discoveries": ["discovery-017"], "poly": "169,470 157,521 121,559 72,550 34,520 18,470 39,424 72,389 119,387 160,417", "center": [95, 470], "journal": "Исследован «Мировой океан». Течения переносят тепло и влияют на климат побережий; солёность зависит от испарения, осадков, рек и льдов."}, {"id": "sector-18", "name": "Население Земли", "type": "population", "chapter": 2, "description": "Ночные снимки показывают скопления огней: в одних местах города сливаются в сплошные пятна, в других на тысячи километров нет ни одного огня.", "geo": "Численность и плотность населения; города и сельские поселения.", "requires": ["sector-16", "sector-17"], "taskIds": ["task-069", "task-070", "task-071", "task-072"], "discoveries": ["discovery-018"], "poly": "1039,352 1028,374 970,388 898,389 853,372 832,352 854,333 903,320 971,316 1016,333", "center": [935, 352], "journal": "Исследовано «Население Земли». Людей на планете более 8 млрд, но живут они неравномерно: плотность зависит от природных и исторических условий."}, {"id": "sector-19", "name": "Народы и хозяйство", "type": "peoples", "chapter": 2, "description": "Тысячи народов говорят на разных языках, исповедуют разные религии и по-разному используют природу. Сканер сопоставляет карты языков, религий и занятости населения.", "geo": "Языковые семьи, мировые религии, виды хозяйственной деятельности, типы стран.", "requires": ["sector-18"], "taskIds": ["task-073", "task-074", "task-075", "task-076"], "discoveries": ["discovery-019"], "poly": "298,645 251,666 204,685 131,680 57,671 59,645 59,619 126,605 205,604 274,619", "center": [165, 645], "journal": "Исследованы «Народы и хозяйство». Народы объединяют по языковым семьям, религии распространены неравномерно, а занятость делят на сельское хозяйство, промышленность и сферу услуг."}, {"id": "sector-20", "name": "Африка", "type": "africa", "chapter": 2, "description": "К югу от Средиземного моря лежит материк, который пересекают экватор и оба тропика. Сканер показывает симметричную смену природных зон к северу и югу от экватора.", "geo": "Самый жаркий материк: природные зоны сменяются симметрично от экватора.", "requires": ["sector-19"], "taskIds": ["task-077", "task-078", "task-079", "task-080"], "discoveries": ["discovery-020"], "poly": "530,330 610,318 680,340 700,420 660,520 600,560 560,470 535,400", "center": [615, 440], "journal": "Исследована «Африка». Материк лежит в жарких поясах, природные зоны сменяются симметрично от экватора: Сахара на севере, Калахари и Намиб на юге."}, {"id": "sector-21", "name": "Южная Америка", "type": "samerica", "chapter": 2, "description": "Западный край материка — непрерывная горная стена, к востоку лежит огромная влажная низменность. Река, текущая по ней, несёт больше воды, чем любая другая.", "geo": "Анды на западе, Амазонская низменность, Бразильское плоскогорье, холодное Перуанское течение.", "requires": ["sector-20"], "taskIds": ["task-081", "task-082", "task-083", "task-084"], "discoveries": ["discovery-021"], "poly": "270,360 350,345 410,385 395,470 350,560 310,600 290,500 265,430", "center": [335, 470], "journal": "Исследована «Южная Америка». Анды возникли на границе плит, Амазонка — самая полноводная река мира, а холодное течение вдоль побережья породило пустыню Атакама."}, {"id": "sector-22", "name": "Австралия и Океания", "type": "australia", "chapter": 2, "description": "Самый маленький материк целиком лежит в Южном полушарии. Вокруг него — тысячи островов, разбросанных по Тихому океану.", "geo": "Материк-государство с пустынями в центре и островная Океания.", "requires": ["sector-20"], "taskIds": ["task-085", "task-086", "task-087", "task-088"], "discoveries": ["discovery-022"], "poly": "830,430 900,400 990,420 1020,490 960,540 870,535 820,490", "center": [915, 478], "journal": "Исследованы «Австралия и Океания». Внутренние районы Австралии засушливы, а долгая изоляция материка создала уникальный животный мир."}, {"id": "sector-23", "name": "Антарктида", "type": "antarctica", "chapter": 2, "description": "На юге планеты лежит материк, покрытый ледяным щитом, где заключено около 90 % льда Земли. Постоянного населения нет, но круглый год работают научные станции.", "geo": "Самый холодный, высокий и ветреный материк; территория международных научных исследований.", "requires": ["sector-22"], "taskIds": ["task-089", "task-090", "task-091", "task-092"], "discoveries": ["discovery-023"], "poly": "330,625 560,600 780,608 860,645 600,676 360,672", "center": [595, 640], "journal": "Исследована «Антарктида». Материк открыли русские моряки в 1820 году; сегодня он принадлежит науке: Договор об Антарктике запрещает военную деятельность."}, {"id": "sector-24", "name": "Северная Америка", "type": "namerica", "chapter": 2, "description": "Материк вытянут от арктических льдов до тропиков. Молодые горы на западе, равнины в центре, старые горы на востоке.", "geo": "Кордильеры, Великие равнины, Аппалачи; климат от арктического до тропического.", "requires": ["sector-21"], "taskIds": ["task-093", "task-094", "task-095", "task-096"], "discoveries": ["discovery-024"], "poly": "200,90 330,70 420,110 400,190 360,240 300,290 255,262 235,200 190,150", "center": [315, 175], "journal": "Исследована «Северная Америка». Рельеф вытянут с севера на юг, поэтому воздушные массы свободно перемещаются между Арктикой и тропиками."}, {"id": "sector-25", "name": "Евразия", "type": "eurasia", "chapter": 2, "description": "Самый большой материк, омываемый четырьмя океанами. Здесь самая высокая гора, самое глубокое озеро и самые большие различия климата на одной широте.", "geo": "Материк с высочайшими горами и крупнейшими равнинами; представлены все климатические пояса.", "requires": ["sector-24"], "taskIds": ["task-097", "task-098", "task-099", "task-100"], "discoveries": ["discovery-025"], "poly": "500,80 640,60 820,55 980,75 1060,160 1010,250 900,290 800,300 740,260 680,300 620,270 560,285 520,240 490,170", "center": [780, 175], "journal": "Исследована «Евразия». Материк так велик, что климат на одной широте сильно меняется от окраин к внутренним районам."}, {"id": "sector-26", "name": "Человек и природа", "type": "society", "chapter": 2, "description": "Данные всех экспедиций сведены вместе. Видно, что человечество меняет природу и что многие проблемы невозможно решить в одиночку.", "geo": "Глобальные проблемы человечества и международное сотрудничество.", "requires": ["sector-23", "sector-25"], "taskIds": ["task-101", "task-102", "task-103", "task-104"], "discoveries": ["discovery-026"], "poly": "165,320 156,347 119,364 74,358 35,346 22,320 36,294 75,284 114,285 150,296", "center": [95, 320], "journal": "Исследовано «Человек и природа». Люди зависят от закономерностей географической оболочки и меняют её; для решения глобальных проблем нужны совместные усилия стран."}], "tasks": [{"id": "task-049", "sectorId": "sector-13", "type": "multiple_choice", "topic": "shell", "title": "Всё связано со всем", "description": "На склонах гор вырубили лес. Через несколько лет почва смыта дождями, реки обмелели и заилились, а местный климат стал суше.", "question": "Какое свойство географической оболочки проявилось в этой цепочке событий?", "hint": "Изменение одного компонента (леса) вызвало изменения других: почвы, вод, климата.", "explanation": "Это целостность: компоненты оболочки (рельеф, воздух, воды, почвы, живые организмы) тесно связаны, поэтому изменение одного из них влечёт изменения остальных.", "extra": false, "complex": false, "fgos": "1.1.7", "options": ["Целостность", "Ритмичность", "Широтная зональность", "Азональность"], "correctAnswer": 0}, {"id": "task-050", "sectorId": "sector-13", "type": "map_click", "topic": "shell", "title": "Какая это зона", "description": "На схеме показаны природные зоны Евразии с севера на юг. Признаки одной из них: зима длинная и очень холодная (до −40 °C), лето короткое и прохладное, повсюду хвойные леса, много болот, почвы бедные.", "question": "Нажми на зону, которая подходит под описание.", "hint": "Деревья есть (значит, это не тундра), но леса хвойные и холодные (значит, это не широколиственные леса).", "explanation": "Это тайга. Её главные признаки — хвойные леса (ель, пихта, сосна, лиственница), холодная зима, избыток влаги при слабом испарении. Севернее лежит тундра без деревьев, южнее — смешанные леса с более тёплым климатом.", "extra": false, "complex": false, "fgos": "1.1.4", "correctZone": "taiga", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "arctic", "label": "Арктические пустыни", "x": 40, "y": 6, "w": 220, "h": 30, "c": "ice"}, {"t": "zone", "id": "tundra", "label": "Тундра", "x": 40, "y": 38, "w": 220, "h": 30, "c": "tundra"}, {"t": "zone", "id": "taiga", "label": "Тайга", "x": 40, "y": 70, "w": 220, "h": 30, "c": "taiga"}, {"t": "zone", "id": "mixed", "label": "Смешанные и широколиственные леса", "x": 40, "y": 102, "w": 220, "h": 34, "c": "forest"}, {"t": "zone", "id": "steppe", "label": "Степи", "x": 40, "y": 138, "w": 220, "h": 34, "c": "steppe"}, {"t": "text", "x": 20, "y": 16, "s": "Север", "sm": true}, {"t": "text", "x": 20, "y": 170, "s": "Юг", "sm": true}]}}, {"id": "task-051", "sectorId": "sector-13", "type": "analysis", "topic": "shell", "title": "Зоны в горах", "description": "У подножия горы (высота 0 м) растут леса, температура воздуха +24 °C. С подъёмом температура понижается на 0,6 °C на каждые 100 м. Вершина горы находится на высоте 4000 м. Выше леса лежат луга, ещё выше — камни, снег и лёд.", "question": "Какая температура будет на вершине и что это говорит о высотной поясности?", "hint": "4000 м — это 40 раз по 100 м. Умножь 40 на 0,6 и вычти результат из +24.", "explanation": "На каждые 100 м температура падает на 0,6 °C: 40 × 0,6 = 24 °C. На вершине около +24 − 24 = 0 °C, поэтому там снег и лёд. Смена поясов в горах повторяет смену зон от экватора к полюсам: с высотой становится холоднее.", "extra": false, "complex": true, "fgos": "1.1.3", "options": ["Около 0 °C: на вершине снег и лёд", "Около +48 °C: чем выше, тем теплее", "Около +24 °C: температура не меняется", "Около −24 °C: на вершине вечная мерзлота"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "poly", "pts": "50,170 250,170 205,108 95,108", "c": "forest"}, {"t": "poly", "pts": "95,108 205,108 178,60 122,60", "c": "low"}, {"t": "poly", "pts": "122,60 178,60 150,22", "c": "ice"}, {"t": "text", "x": 150, "y": 150, "s": "Лес, 0 м, +24 °C"}, {"t": "text", "x": 150, "y": 90, "s": "Горные луга"}, {"t": "text", "x": 150, "y": 50, "s": "Снег и лёд", "sm": true}, {"t": "dot", "x": 150, "y": 22, "label": "Вершина, 4000 м"}]}}, {"id": "task-052", "sectorId": "sector-13", "type": "identify", "topic": "shell", "title": "Повторяющиеся явления", "description": "Каждый год в умеренных широтах после зимы приходит весна, затем лето и осень. Каждые сутки сменяются день и ночь.", "question": "Какое свойство географической оболочки проявляется в повторяемости этих явлений?", "hint": "Речь о повторении через равные промежутки времени.", "explanation": "Это ритмичность: многие процессы в оболочке повторяются во времени (сутки, год). Целостность — взаимосвязь компонентов, зональность — закономерная смена природы от экватора к полюсам.", "extra": true, "complex": false, "fgos": "1.1.2", "options": ["Ритмичность", "Целостность", "Широтная зональность", "Азональность"], "correctAnswer": 0}, {"id": "task-053", "sectorId": "sector-14", "type": "multiple_choice", "topic": "litho", "title": "Столкновение материков", "description": "Две материковые плиты движутся навстречу друг другу. Ни одна из них не погружается в мантию полностью: земная кора сминается в складки. Так образовались, например, Гималаи.", "question": "Что образуется на границе сталкивающихся материковых плит?", "hint": "Подумай, что станет с корой, если две толстые плиты давят друг на друга.", "explanation": "При столкновении материковых плит кора сминается и вздымается: образуются высокие складчатые горы. Индостанская плита сближается с Евразийской, поэтому Гималаи продолжают расти, а в этом районе часты землетрясения.", "extra": false, "complex": false, "fgos": "1.2.2", "options": ["Высокие складчатые горы", "Срединно-океанический хребет", "Рифтовая долина с вулканами на дне океана", "Обширная равнина"], "correctAnswer": 0}, {"id": "task-054", "sectorId": "sector-14", "type": "map_click", "topic": "litho", "title": "Где неспокойно", "description": "На схеме в разрезе показана литосферная плита с материком и соседняя океаническая плита, которая медленно погружается под материк. Приборы расположены в трёх областях.", "question": "Где чаще всего происходят сильные землетрясения и действуют вулканы? Нажми на область.", "hint": "Движение плит всего заметнее там, где они соприкасаются.", "explanation": "Землетрясения и вулканизм сосредоточены вдоль границ литосферных плит. Здесь образуются глубоководные жёлоба, цепи вулканов и горные системы. В середине плит (платформы) и вдали от границ земная кора спокойнее.", "extra": false, "complex": false, "fgos": "1.2.2", "correctZone": "border", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "centre", "label": "Равнина в центре материковой плиты", "x": 8, "y": 20, "w": 92, "h": 140, "c": "low"}, {"t": "zone", "id": "border", "label": "Граница плит: глубоководный жёлоб, горы, вулканы", "x": 104, "y": 20, "w": 92, "h": 140, "c": "lava"}, {"t": "zone", "id": "ocean", "label": "Океаническое дно вдали от границы", "x": 200, "y": 20, "w": 92, "h": 140, "c": "water"}, {"t": "text", "x": 150, "y": 12, "s": "Разрез литосферных плит", "sm": true}]}}, {"id": "task-055", "sectorId": "sector-14", "type": "analysis", "topic": "litho", "title": "Событие в новостях", "description": "В сообщении сказано: «На острове в Тихом океане началось извержение вулкана. В течение месяца сейсмографы зафиксировали серию подземных толчков вдоль глубоководного жёлоба у побережья. Остров входит в Тихоокеанское огненное кольцо».", "question": "Чем лучше всего объясняются и извержение, и землетрясения?", "hint": "Найди в тексте слова, указывающие на границы плит: «жёлоб», «огненное кольцо».", "explanation": "Вокруг Тихого океана океаническая плита погружается под соседние плиты. На границе происходят толчки, а погружающаяся кора плавится и даёт магму: поэтому здесь много и землетрясений, и вулканов. Это характерно для всего Тихоокеанского огненного кольца.", "extra": false, "complex": true, "fgos": "1.2.2", "options": ["Остров расположен на границе литосферных плит, где одна плита погружается под другую", "Остров дрейфует из-за морских течений и ветров", "На острове нет границ плит, извержения происходят случайно", "Дно океана высыхает и растрескивается"], "correctAnswer": 0}, {"id": "task-056", "sectorId": "sector-14", "type": "identify", "topic": "litho", "title": "Где искать руду", "description": "Геологи ищут месторождения руд (железной, медной, золотой) и знают, что руды часто связаны с древним кристаллическим фундаментом и областями горообразования.", "question": "К каким областям земной коры приурочены рудные полезные ископаемые?", "hint": "Горючие ископаемые (нефть, уголь) образуются в осадочных породах равнин, а руды связаны с магматическими и метаморфическими породами.", "explanation": "Рудные полезные ископаемые чаще встречаются в горах и на выступах фундамента платформ (щитах), где распространены магматические и метаморфические горные породы. Нефть, газ и уголь — в осадочном чехле платформ.", "extra": true, "complex": false, "fgos": "1.1.8", "options": ["Щиты платформ и горные области", "Осадочный чехол равнин", "Дно озёр и болот", "Ледниковые равнины"], "correctAnswer": 0}, {"id": "task-057", "sectorId": "sector-15", "type": "multiple_choice", "topic": "atmo", "title": "Постоянные ветры тропиков", "description": "В области высокого давления около 30° с. и ю. ш. воздух опускается и расходится вдоль поверхности. Часть потока направляется к экватору, где давление низкое, и отклоняется вращением Земли к западу.", "question": "Как называются постоянные ветры, дующие из тропических широт к экватору?", "hint": "Они помогали парусным кораблям пересекать океаны: «дуют с востока на запад» в тропиках.", "explanation": "Это пассаты: постоянные ветры тропических широт, дующие от поясов высокого давления (около 30°) к экватору. Благодаря вращению Земли они отклоняются и дуют в основном с востока на запад.", "extra": false, "complex": false, "fgos": "1.3.3", "options": ["Пассаты", "Западные ветры умеренных широт", "Муссоны", "Бризы"], "correctAnswer": 0}, {"id": "task-058", "sectorId": "sector-15", "type": "map_click", "topic": "atmo", "title": "Пояса давления", "description": "На схеме показаны пояса атмосферного давления северного полушария от экватора до полюса. В одном из поясов тёплый влажный воздух поднимается вверх, охлаждается и даёт ливни.", "question": "Нажми на пояс низкого давления с восходящими потоками воздуха и ежедневными ливнями.", "hint": "Тёплый воздух легче холодного. Где на Земле солнце греет сильнее всего?", "explanation": "На экваторе поверхность сильно нагревается, воздух поднимается вверх, давление у земли низкое, пар конденсируется и выпадают обильные осадки. В тропиках (около 30°) воздух опускается, давление высокое, осадков мало.", "extra": false, "complex": false, "fgos": "1.3.4", "correctZone": "eq", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "pole", "label": "Полюс, 90°: высокое давление", "x": 60, "y": 6, "w": 200, "h": 36, "c": "ice"}, {"t": "zone", "id": "temp", "label": "Умеренные широты, около 60°: низкое давление", "x": 60, "y": 46, "w": 200, "h": 36, "c": "forest"}, {"t": "zone", "id": "trop", "label": "Тропики, около 30°: высокое давление", "x": 60, "y": 86, "w": 200, "h": 36, "c": "dry"}, {"t": "zone", "id": "eq", "label": "Экватор, 0°: низкое давление", "x": 60, "y": 126, "w": 200, "h": 36, "c": "eq"}, {"t": "text", "x": 30, "y": 20, "s": "Север", "sm": true}, {"t": "text", "x": 30, "y": 168, "s": "Юг", "sm": true}]}}, {"id": "task-059", "sectorId": "sector-15", "type": "analysis", "topic": "atmo", "title": "Летний муссон", "description": "Летом суша нагрелась сильнее океана. Давление у поверхности суши 1006 гПа, над океаном — 1014 гПа. Побережье расположено в тропических широтах, ветер не отклоняется.", "question": "В каком направлении дует ветер и что он приносит?", "hint": "Ветер дует из области высокого давления в область низкого. Сравни числа.", "explanation": "Воздух движется от большего давления (океан, 1014 гПа) к меньшему (суша, 1006 гПа). Океанический воздух влажный, поэтому летний муссон приносит на сушу ливни. Зимой суша остывает, давление над ней повышается, и муссон дует с суши на океан — сухой.", "extra": false, "complex": true, "fgos": "1.3.3", "options": ["С океана на сушу, приносит обильные осадки", "С суши на океан, несёт сухой воздух", "Ветра не будет, давление выровняется само", "С экватора на полюс"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "rect", "x": 0, "y": 0, "w": 130, "h": 180, "c": "water"}, {"t": "rect", "x": 130, "y": 0, "w": 170, "h": 180, "c": "land"}, {"t": "text", "x": 65, "y": 70, "s": "Океан"}, {"t": "text", "x": 65, "y": 90, "s": "1014 гПа"}, {"t": "text", "x": 215, "y": 70, "s": "Суша"}, {"t": "text", "x": 215, "y": 90, "s": "1006 гПа"}, {"t": "text", "x": 150, "y": 14, "s": "Лето", "sm": true}]}}, {"id": "task-060", "sectorId": "sector-15", "type": "identify", "topic": "atmo", "title": "Воздушная масса", "description": "Воздух сформировался над ледяной поверхностью у полюса: он очень холодный, сухой и прозрачный.", "question": "К какому типу относится эта воздушная масса?", "hint": "Типы воздушных масс по широтам: экваториальные, тропические, умеренные, арктические (антарктические).", "explanation": "Воздушные массы получают свойства от поверхности, над которой формируются. Над ледяными пространствами полярных областей образуется арктический (в южном полушарии — антарктический) воздух: холодный и сухой.", "extra": true, "complex": false, "fgos": "1.3.2", "options": ["Арктический (антарктический)", "Экваториальный", "Тропический морской", "Умеренный морской"], "correctAnswer": 0}, {"id": "task-061", "sectorId": "sector-16", "type": "multiple_choice", "topic": "climates", "title": "Почему жарко на экваторе", "description": "На экваторе круглый год жарко, а у полюсов холодно. Солнечные лучи падают на поверхность под разными углами.", "question": "Какой климатообразующий фактор главнее всего объясняет эту разницу?", "hint": "В какой точке Земли солнечные лучи падают почти отвесно?", "explanation": "Главный фактор — географическая широта. Чем она ниже, тем больше угол падения лучей, тем больше тепла получает поверхность. К другим факторам относятся течения, циркуляция воздуха, рельеф и подстилающая поверхность.", "extra": false, "complex": false, "fgos": "1.3.6", "options": ["Географическая широта", "Высота над уровнем моря", "Океанические течения", "Удалённость от океана"], "correctAnswer": 0}, {"id": "task-062", "sectorId": "sector-16", "type": "map_click", "topic": "climates", "title": "Какой пояс", "description": "Три метеостанции передали данные за год. Нужно найти станцию, расположенную в экваториальном климатическом поясе.", "question": "Нажми на пункт, расположенный в экваториальном поясе.", "hint": "Для экваториального пояса характерны жарко круглый год (без зимы) и очень много осадков.", "explanation": "Экваториальный пояс: температура круглый год около +25…+27 °C, осадков более 2000 мм, сезонов нет. Пункт Б (жаркое лето, мало осадков) — тропическая пустыня; пункт В (холодная зима, умеренное лето, средние осадки) — умеренный пояс.", "extra": false, "complex": false, "fgos": "1.3.2", "correctZone": "a", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "a", "label": "Пункт А: июль +25 °C, январь +26 °C, осадков 2800 мм", "x": 6, "y": 14, "w": 92, "h": 152, "c": "card"}, {"t": "zone", "id": "b", "label": "Пункт Б: июль +30 °C, январь +14 °C, осадков 80 мм", "x": 104, "y": 14, "w": 92, "h": 152, "c": "card"}, {"t": "zone", "id": "v", "label": "Пункт В: июль +17 °C, январь −8 °C, осадков 600 мм", "x": 202, "y": 14, "w": 92, "h": 152, "c": "card"}]}}, {"id": "task-063", "sectorId": "sector-16", "type": "analysis", "topic": "climates", "title": "Читаем климатограмму", "description": "На климатограмме показаны средние месячные температуры воздуха (линия) и осадки (столбики) одного города. Месяцы идут с января по декабрь. Город расположен в северном полушарии.", "question": "Какой вывод о климате правильный?", "hint": "Посмотри, когда температура самая высокая и когда выпадает больше осадков. Совпадают ли эти месяцы?", "explanation": "Зима тёплая (около +9…+10 °C) и дождливая, лето жаркое (около +26 °C) и почти без осадков. Это признак средиземноморского (субтропического) климата: осадки приносят влажные ветры зимой, а летом устанавливается область высокого давления.", "extra": false, "complex": true, "fgos": "1.3.5", "options": ["Тёплая дождливая зима и жаркое сухое лето — субтропический средиземноморский климат", "Осадки выпадают летом, зимой сухо — муссонный климат", "Температура и осадки круглый год почти не меняются — экваториальный климат", "Круглый год жарко и сухо — тропическая пустыня"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "line", "pts": "30,118.0 268,118.0", "c": "axis"}, {"t": "text", "x": 27, "y": 121.0, "s": "10°", "a": "end", "sm": true}, {"t": "line", "pts": "30,86.0 268,86.0", "c": "axis"}, {"t": "text", "x": 27, "y": 89.0, "s": "20°", "a": "end", "sm": true}, {"t": "line", "pts": "30,54.0 268,54.0", "c": "axis"}, {"t": "text", "x": 27, "y": 57.0, "s": "30°", "a": "end", "sm": true}, {"t": "text", "x": 271, "y": 118.0, "s": "100", "a": "start", "sm": true}, {"t": "text", "x": 271, "y": 83.0, "s": "200", "a": "start", "sm": true}, {"t": "rect", "x": 33.0, "y": 116.8, "w": 13.8, "h": 33.2, "c": "prec"}, {"t": "rect", "x": 52.8, "y": 122.0, "w": 13.8, "h": 28.0, "c": "prec"}, {"t": "rect", "x": 72.7, "y": 127.2, "w": 13.8, "h": 22.8, "c": "prec"}, {"t": "rect", "x": 92.5, "y": 136.0, "w": 13.8, "h": 14.0, "c": "prec"}, {"t": "rect", "x": 112.3, "y": 141.2, "w": 13.8, "h": 8.8, "c": "prec"}, {"t": "rect", "x": 132.2, "y": 146.5, "w": 13.8, "h": 3.5, "c": "prec"}, {"t": "rect", "x": 152.0, "y": 149.0, "w": 13.8, "h": 1.0, "c": "prec"}, {"t": "rect", "x": 171.8, "y": 147.9, "w": 13.8, "h": 2.1, "c": "prec"}, {"t": "rect", "x": 191.7, "y": 140.2, "w": 13.8, "h": 9.8, "c": "prec"}, {"t": "rect", "x": 211.5, "y": 129.0, "w": 13.8, "h": 21.0, "c": "prec"}, {"t": "rect", "x": 231.3, "y": 118.5, "w": 13.8, "h": 31.5, "c": "prec"}, {"t": "rect", "x": 251.2, "y": 113.2, "w": 13.8, "h": 36.8, "c": "prec"}, {"t": "line", "pts": "39.9,121.2 59.7,118.0 79.6,111.6 99.4,102.0 119.2,89.2 139.1,76.4 158.9,66.8 178.7,66.8 198.6,76.4 218.4,92.4 238.2,108.4 258.1,118.0", "c": "temp"}, {"t": "line", "pts": "30,150 268,150", "c": "axis"}, {"t": "text", "x": 39.9, "y": 162, "s": "Я", "sm": true}, {"t": "text", "x": 59.7, "y": 162, "s": "Ф", "sm": true}, {"t": "text", "x": 79.6, "y": 162, "s": "М", "sm": true}, {"t": "text", "x": 99.4, "y": 162, "s": "А", "sm": true}, {"t": "text", "x": 119.2, "y": 162, "s": "М", "sm": true}, {"t": "text", "x": 139.1, "y": 162, "s": "И", "sm": true}, {"t": "text", "x": 158.9, "y": 162, "s": "И", "sm": true}, {"t": "text", "x": 178.7, "y": 162, "s": "А", "sm": true}, {"t": "text", "x": 198.6, "y": 162, "s": "С", "sm": true}, {"t": "text", "x": 218.4, "y": 162, "s": "О", "sm": true}, {"t": "text", "x": 238.2, "y": 162, "s": "Н", "sm": true}, {"t": "text", "x": 258.1, "y": 162, "s": "Д", "sm": true}, {"t": "text", "x": 78, "y": 12, "s": "Линия: температура, °C", "sm": true}, {"t": "text", "x": 205, "y": 12, "s": "Столбики: осадки, мм", "sm": true}]}}, {"id": "task-064", "sectorId": "sector-16", "type": "identify", "topic": "climates", "title": "Человек и атмосфера", "description": "При сжигании угля, нефти и газа в атмосферу поступает много углекислого газа. Он задерживает часть тепла, уходящего от поверхности Земли.", "question": "Как называют усиление этого эффекта, которое связывают с потеплением климата?", "hint": "Название связано с плёнкой теплицы, которая задерживает тепло.", "explanation": "Это усиление парникового эффекта. Многие учёные считают, что рост концентрации парниковых газов вызывает потепление климата; мнения о вкладе человека и природных причин различаются, но наблюдения показывают рост средней температуры.", "extra": true, "complex": false, "fgos": "1.3.8", "options": ["Усиление парникового эффекта", "Образование озоновых дыр", "Смена направления пассатов", "Ритмичность природы"], "correctAnswer": 0}, {"id": "task-065", "sectorId": "sector-17", "type": "multiple_choice", "topic": "ocean", "title": "Самый большой океан", "description": "Мировой океан делят на четыре океана: Тихий, Атлантический, Индийский и Северный Ледовитый. Один из них занимает около трети поверхности планеты и имеет самую большую глубину — около 11 км в Марианском жёлобе.", "question": "Какой это океан?", "hint": "Его воды омывают берега Азии, Америки, Австралии и Антарктиды.", "explanation": "Это Тихий океан — самый большой и глубокий. Его площадь больше, чем площадь всей суши Земли.", "extra": false, "complex": false, "fgos": "1.4.1", "options": ["Тихий", "Атлантический", "Индийский", "Северный Ледовитый"], "correctAnswer": 0}, {"id": "task-066", "sectorId": "sector-17", "type": "map_click", "topic": "ocean", "title": "Тёплые и холодные течения", "description": "На схеме материк в тропических широтах. Пассаты дуют с востока на запад. Вдоль одних берегов вода течёт от полюса к экватору и несёт холод (как Перуанское и Бенгельское течения), вдоль других — от экватора к полюсу и несёт тепло (как Бразильское и Мозамбикское).", "question": "Нажми на область, где вероятнее всего проходит тёплое течение.", "hint": "Пассаты гонят поверхностную воду на запад. Подумай, где она «упирается» в берег материка.", "explanation": "В тропических широтах тёплые течения проходят у восточных берегов материков, а холодные — у западных. Поверхностные воды, увлекаемые пассатами на запад, упираются в восточный берег и поворачивают к полюсу; у западных берегов вода приходит из высоких широт.", "extra": false, "complex": false, "fgos": "1.4.2", "correctZone": "east", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "water"}, {"t": "rect", "x": 100, "y": 44, "w": 100, "h": 132, "c": "land"}, {"t": "zone", "id": "north", "label": "Воды у северного берега", "x": 100, "y": 4, "w": 100, "h": 36, "c": "water"}, {"t": "zone", "id": "west", "label": "Воды у западного берега", "x": 8, "y": 50, "w": 88, "h": 120, "c": "water"}, {"t": "zone", "id": "east", "label": "Воды у восточного берега", "x": 204, "y": 50, "w": 88, "h": 120, "c": "water"}, {"t": "text", "x": 150, "y": 112, "s": "Материк"}, {"t": "text", "x": 150, "y": 128, "s": "в тропиках"}]}}, {"id": "task-067", "sectorId": "sector-17", "type": "analysis", "topic": "ocean", "title": "Солёность воды", "description": "Средняя солёность поверхностных вод Мирового океана около 35 ‰. По широтам она различается: экватор около 34 ‰, тропики около 36 ‰, умеренные широты около 35 ‰, полярные районы около 32 ‰ (значения округлены).", "question": "Чем объясняется самая высокая солёность в тропических широтах?", "hint": "Посмотри, где много испарения и мало осадков, а где пресная вода добавляется от рек, дождей и ледников.", "explanation": "В тропиках (область высокого давления) жарко, осадков мало, а испарение велико. Вода испаряется, а соли остаются, поэтому солёность выше. У экватора ливни опресняют воду, у полюсов — тающие льды и реки.", "extra": false, "complex": true, "fgos": "1.4.4", "options": ["Там сильное испарение и мало осадков", "Там впадает больше рек", "Там много тающих льдов", "Там самая низкая температура воды"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "rect", "x": 30, "y": 78, "w": 45, "h": 72, "c": "bar"}, {"t": "rect", "x": 95, "y": 42, "w": 45, "h": 108, "c": "bar"}, {"t": "rect", "x": 160, "y": 60, "w": 45, "h": 90, "c": "bar"}, {"t": "rect", "x": 225, "y": 114, "w": 45, "h": 36, "c": "bar"}, {"t": "text", "x": 52, "y": 72, "s": "34 ‰", "sm": true}, {"t": "text", "x": 117, "y": 36, "s": "36 ‰", "sm": true}, {"t": "text", "x": 182, "y": 54, "s": "35 ‰", "sm": true}, {"t": "text", "x": 247, "y": 108, "s": "32 ‰", "sm": true}, {"t": "text", "x": 52, "y": 164, "s": "Экватор", "sm": true}, {"t": "text", "x": 117, "y": 164, "s": "Тропики", "sm": true}, {"t": "text", "x": 182, "y": 164, "s": "Умеренные", "sm": true}, {"t": "text", "x": 247, "y": 164, "s": "Полярные", "sm": true}, {"t": "text", "x": 150, "y": 14, "s": "Солёность поверхностных вод", "sm": true}]}}, {"id": "task-068", "sectorId": "sector-17", "type": "identify", "topic": "ocean", "title": "Беда на воде", "description": "После аварии танкера на поверхности океана появилось огромное пятно с радужной плёнкой. Гибнут птицы и морские животные, побережье покрыто чёрной липкой массой.", "question": "Какая экологическая проблема Мирового океана здесь проявилась?", "hint": "Плёнка на воде и нефтяные пятна — причина гибели птиц.", "explanation": "Это загрязнение океана нефтью и нефтепродуктами. Нефтяная плёнка мешает обмену газов между водой и воздухом, убивает планктон, рыб и птиц. Для борьбы с последствиями нужны международные усилия.", "extra": true, "complex": false, "fgos": "1.4.7", "options": ["Загрязнение нефтью", "Повышение уровня океана", "Повышение солёности", "Таяние ледников"], "correctAnswer": 0}, {"id": "task-069", "sectorId": "sector-18", "type": "multiple_choice", "topic": "population", "title": "Самые людные страны", "description": "Население мира превышает 8 млрд человек. Больше 1,4 млрд человек живёт в каждой из двух стран Азии, на которые приходится около трети всего человечества.", "question": "Какие это страны?", "hint": "Это две самые большие по численности населения страны мира. Обе находятся в Азии.", "explanation": "Это Индия и Китай. Каждая из них имеет население более 1,4 млрд человек. Индия в последние годы обогнала Китай по численности населения. Крупнейшие страны по населению следом — США, Индонезия и Пакистан.", "extra": false, "complex": false, "fgos": "2.1.2", "options": ["Индия и Китай", "Китай и США", "Индия и Россия", "Индонезия и Бразилия"], "correctAnswer": 0}, {"id": "task-070", "sectorId": "sector-18", "type": "map_click", "topic": "population", "title": "Где людей больше всего", "description": "Четыре территории показаны на схеме с данными о числе жителей и площади. Плотность населения — это число жителей, приходящееся на 1 км² (чел./км²).", "question": "Нажми на территорию с самой высокой плотностью населения.", "hint": "Плотность = число жителей ÷ площадь. Переведи миллионы и тысячи в одни единицы: 1 млн ÷ 1 тыс. = 1000.", "explanation": "Речная равнина: 40 млн ÷ 100 тыс. км² = 400 чел./км². Плоскогорье: 10 млн ÷ 200 тыс. = 50. Горы: 2 млн ÷ 80 тыс. = 25. Пустыня: 1 млн ÷ 500 тыс. = 2. Самая высокая плотность — на речной равнине.", "extra": false, "complex": false, "fgos": "2.1.3", "correctZone": "plain", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "plain", "label": "Речная равнина: 40 млн чел., 100 тыс. км²", "x": 8, "y": 8, "w": 140, "h": 76, "c": "low"}, {"t": "zone", "id": "plateau", "label": "Плоскогорье: 10 млн чел., 200 тыс. км²", "x": 152, "y": 8, "w": 140, "h": 76, "c": "hill"}, {"t": "zone", "id": "mount", "label": "Горы: 2 млн чел., 80 тыс. км²", "x": 8, "y": 90, "w": 140, "h": 80, "c": "mount"}, {"t": "zone", "id": "desert", "label": "Пустыня: 1 млн чел., 500 тыс. км²", "x": 152, "y": 90, "w": 140, "h": 80, "c": "dry"}]}}, {"id": "task-071", "sectorId": "sector-18", "type": "analysis", "topic": "population", "title": "Сравнить плотность", "description": "Страна А: население 146 млн человек, площадь 17,1 млн км². Страна Б: население 125 млн человек, площадь 0,38 млн км². Обе имеют сопоставимую численность населения, но территории совершенно разные.", "question": "Во сколько примерно раз плотность населения страны Б больше плотности страны А?", "hint": "Посчитай плотность каждой страны: население ÷ площадь. Затем раздели большее число на меньшее.", "explanation": "Плотность А: 146 ÷ 17,1 ≈ 8,5 чел./км². Плотность Б: 125 ÷ 0,38 ≈ 330 чел./км². 330 ÷ 8,5 ≈ 39, то есть примерно в 40 раз. Численность населения у стран близка, а плотность отличается резко: она зависит от площади территории и природных условий.", "extra": false, "complex": true, "fgos": "2.1.4", "options": ["Примерно в 40 раз", "Примерно в 4 раза", "Примерно в 400 раз", "Плотность одинакова"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "text", "x": 150, "y": 30, "s": "Страна А", "sm": true}, {"t": "text", "x": 150, "y": 50, "s": "146 млн чел.; 17,1 млн км²"}, {"t": "text", "x": 150, "y": 100, "s": "Страна Б", "sm": true}, {"t": "text", "x": 150, "y": 120, "s": "125 млн чел.; 0,38 млн км²"}]}}, {"id": "task-072", "sectorId": "sector-18", "type": "identify", "topic": "population", "title": "Город или село", "description": "В поселении живёт около 2 млн человек. Преобладают многоэтажные здания, большая часть жителей работает в промышленности, торговле, образовании и других отраслях вне сельского хозяйства.", "question": "К какому типу поселений оно относится?", "hint": "Сельские жители заняты в основном в сельском хозяйстве.", "explanation": "Это город. Для городов характерны большая численность, плотная застройка и занятость жителей в промышленности и сфере услуг. В сельских поселениях основное занятие — земледелие и животноводство.", "extra": true, "complex": false, "fgos": "2.1.5", "options": ["Город", "Сельское поселение", "Кочевая стоянка", "Рабочий посёлок при шахте"], "correctAnswer": 0}, {"id": "task-073", "sectorId": "sector-19", "type": "multiple_choice", "topic": "peoples", "title": "Языковая семья", "description": "Народы мира объединяют в языковые семьи по сходству языков. Русский, английский, немецкий, испанский, хинди относятся к одной из самых больших семей по числу говорящих.", "question": "К какой языковой семье относится русский язык?", "hint": "Эта семья названа по двум регионам: от Индии до Европы.", "explanation": "Русский язык относится к индоевропейской языковой семье (славянская группа). К ней же относятся английский, испанский, хинди и многие другие языки. Китайский принадлежит к китайско-тибетской, арабский — к афразийской семье.", "extra": false, "complex": false, "fgos": "2.2.2", "options": ["Индоевропейская", "Китайско-тибетская", "Афразийская", "Алтайская"], "correctAnswer": 0}, {"id": "task-074", "sectorId": "sector-19", "type": "map_click", "topic": "peoples", "title": "Мировые религии", "description": "Различают мировые религии (христианство, ислам, буддизм) и национальные (например, индуизм, иудаизм). Они распространены неравномерно. На схеме указаны регионы и страны.", "question": "В каком регионе большинство населения исповедует ислам?", "hint": "Священная книга мусульман — Коран, храм — мечеть.", "explanation": "Ислам преобладает в Саудовской Аравии, Иране, Египте и в других странах Северной Африки и Юго-Западной Азии. В Бразилии, Италии и Мексике преобладает христианство, в Таиланде и Мьянме — буддизм, в Индии — индуизм.", "extra": false, "complex": false, "fgos": "2.2.1", "correctZone": "islam", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "christ", "label": "Бразилия, Италия, Мексика", "x": 8, "y": 8, "w": 140, "h": 76, "c": "card"}, {"t": "zone", "id": "islam", "label": "Саудовская Аравия, Иран, Египет", "x": 152, "y": 8, "w": 140, "h": 76, "c": "card"}, {"t": "zone", "id": "budd", "label": "Таиланд, Мьянма, Шри-Ланка", "x": 8, "y": 90, "w": 140, "h": 80, "c": "card"}, {"t": "zone", "id": "hindu", "label": "Индия, Непал", "x": 152, "y": 90, "w": 140, "h": 80, "c": "card"}]}}, {"id": "task-075", "sectorId": "sector-19", "type": "analysis", "topic": "peoples", "title": "Чем заняты люди", "description": "На диаграмме показано распределение занятых по видам хозяйственной деятельности в двух странах.", "question": "Какой вывод можно сделать?", "hint": "Сопоставь длину цветных отрезков: зелёный — сельское хозяйство, коричневый — промышленность, синий — услуги.", "explanation": "В стране А больше половины занятых (55 %) работают в сельском хозяйстве — так бывает в странах с низким уровнем развития. В стране Б 78 % занятых — в сфере услуг: торговля, транспорт, образование, туризм; это признак развитого хозяйства.", "extra": false, "complex": true, "fgos": "2.2.3", "options": ["В стране А преобладает занятость в сельском хозяйстве, в стране Б — в сфере услуг", "В обеих странах преобладает промышленность", "В стране Б большинство занято в сельском хозяйстве", "Структура занятости в странах одинакова"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "text", "x": 150, "y": 16, "s": "Занятость населения", "sm": true}, {"t": "text", "x": 24, "y": 44, "s": "А", "sm": true}, {"t": "rect", "x": 40, "y": 32, "w": 132, "h": 28, "c": "farm"}, {"t": "rect", "x": 172, "y": 32, "w": 36, "h": 28, "c": "warm"}, {"t": "rect", "x": 208, "y": 32, "w": 72, "h": 28, "c": "cold"}, {"t": "text", "x": 106, "y": 51, "s": "55 %", "sm": true}, {"t": "text", "x": 190, "y": 51, "s": "15 %", "sm": true}, {"t": "text", "x": 244, "y": 51, "s": "30 %", "sm": true}, {"t": "text", "x": 24, "y": 104, "s": "Б", "sm": true}, {"t": "rect", "x": 40, "y": 92, "w": 5, "h": 28, "c": "farm"}, {"t": "rect", "x": 45, "y": 92, "w": 48, "h": 28, "c": "warm"}, {"t": "rect", "x": 93, "y": 92, "w": 187, "h": 28, "c": "cold"}, {"t": "text", "x": 69, "y": 111, "s": "20 %", "sm": true}, {"t": "text", "x": 186, "y": 111, "s": "78 %", "sm": true}, {"t": "text", "x": 42, "y": 86, "s": "2 %", "a": "start", "sm": true}, {"t": "text", "x": 30, "y": 150, "s": "зелёный — сельское хозяйство", "a": "start", "sm": true}, {"t": "text", "x": 30, "y": 164, "s": "коричневый — промышленность, синий — услуги", "a": "start", "sm": true}]}}, {"id": "task-076", "sectorId": "sector-19", "type": "identify", "topic": "peoples", "title": "Профессия менеджера туризма", "description": "Менеджер в сфере туризма и экскурсовод организуют поездки, рассказывают о достопримечательностях, помогают гостям. Они не выращивают урожай и не производят товары.", "question": "К какой сфере хозяйственной деятельности относятся эти профессии?", "hint": "Это деятельность, где результат — услуга, а не вещь и не урожай.", "explanation": "Это сфера услуг. Она включает торговлю, транспорт, образование, здравоохранение, туризм и другие виды деятельности, результатом которых являются услуги. В развитых странах именно в этой сфере занято большинство населения.", "extra": true, "complex": false, "fgos": "2.2.3", "options": ["Сфера услуг", "Сельское хозяйство", "Промышленность", "Добыча полезных ископаемых"], "correctAnswer": 0}, {"id": "task-077", "sectorId": "sector-20", "type": "multiple_choice", "topic": "continents", "title": "Положение Африки", "description": "Африку омывают Атлантический и Индийский океаны, Средиземное и Красное моря. Материк вытянут по обе стороны от экватора.", "question": "Какой материк пересекают экватор и оба тропика?", "hint": "Тропик Рака — 23,5° с. ш., тропик Козерога — 23,5° ю. ш. Нужен материк, на который попадают оба тропика и экватор.", "explanation": "Это Африка: она единственный материк, которого касаются сразу экватор, северный и южный тропики. Поэтому большая часть Африки лежит в жарких климатических поясах.", "extra": false, "complex": false, "fgos": "3.1.1", "options": ["Африка", "Южная Америка", "Австралия", "Евразия"], "correctAnswer": 0}, {"id": "task-078", "sectorId": "sector-20", "type": "map_click", "topic": "continents", "title": "Природные зоны Африки", "description": "Африка лежит по обе стороны от экватора. Природные зоны сменяются симметрично: к северу и югу от экватора. Нужна зона с круглогодичной жарой (+25…+27 °C) и ежедневными ливнями: осадков более 2000 мм в год.", "question": "Нажми на зону, подходящую под описание.", "hint": "Эта зона расположена на экваторе, в бассейне реки Конго.", "explanation": "Влажные экваториальные леса растут вблизи экватора, где круглый год жарко и ливни. К северу и югу от них — саванны с чередованием влажного и сухого сезонов, а ещё дальше — пустыни Сахара (на севере) и Калахари с Намибом (на юге).", "extra": false, "complex": false, "fgos": "3.1.5", "correctZone": "equ", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "sahara", "label": "Пустыня Сахара", "x": 40, "y": 6, "w": 220, "h": 28, "c": "sand"}, {"t": "zone", "id": "savn", "label": "Саванны", "x": 40, "y": 36, "w": 220, "h": 28, "c": "sav"}, {"t": "zone", "id": "equ", "label": "Влажные экваториальные леса", "x": 40, "y": 66, "w": 220, "h": 46, "c": "eq"}, {"t": "zone", "id": "savs", "label": "Саванны", "x": 40, "y": 114, "w": 220, "h": 28, "c": "sav"}, {"t": "zone", "id": "kal", "label": "Пустыни Калахари и Намиб", "x": 40, "y": 144, "w": 220, "h": 30, "c": "sand"}, {"t": "text", "x": 20, "y": 20, "s": "Север", "sm": true}, {"t": "text", "x": 20, "y": 168, "s": "Юг", "sm": true}]}}, {"id": "task-079", "sectorId": "sector-20", "type": "analysis", "topic": "continents", "title": "Экваториальная климатограмма", "description": "На климатограмме показан годовой ход температур и осадков в экваториальном поясе (бассейн Конго). Температура держится около +25 °C, осадков много в каждом месяце.", "question": "Почему температура почти не меняется в течение года?", "hint": "Подумай, как Солнце стоит над горизонтом на экваторе в разные месяцы.", "explanation": "На экваторе Солнце весь год стоит высоко, солнечные лучи падают под углом, близким к прямому, поэтому поверхность прогревается одинаково. Сезонов нет, годовая амплитуда температур не превышает 1–2 °C. Осадки выпадают круглый год, с двумя небольшими максимумами после равноденствий.", "extra": false, "complex": true, "fgos": "3.1.5", "options": ["Солнце круглый год стоит высоко, лучи падают почти отвесно", "Рядом нет океана, поэтому воздух не нагревается", "Круглый год дуют холодные ветры", "Здесь самое высокое атмосферное давление"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "line", "pts": "30,118.0 268,118.0", "c": "axis"}, {"t": "text", "x": 27, "y": 121.0, "s": "10°", "a": "end", "sm": true}, {"t": "line", "pts": "30,86.0 268,86.0", "c": "axis"}, {"t": "text", "x": 27, "y": 89.0, "s": "20°", "a": "end", "sm": true}, {"t": "line", "pts": "30,54.0 268,54.0", "c": "axis"}, {"t": "text", "x": 27, "y": 57.0, "s": "30°", "a": "end", "sm": true}, {"t": "text", "x": 271, "y": 118.0, "s": "100", "a": "start", "sm": true}, {"t": "text", "x": 271, "y": 83.0, "s": "200", "a": "start", "sm": true}, {"t": "rect", "x": 33.0, "y": 76.5, "w": 13.8, "h": 73.5, "c": "prec"}, {"t": "rect", "x": 52.8, "y": 80.0, "w": 13.8, "h": 70.0, "c": "prec"}, {"t": "rect", "x": 72.7, "y": 66.0, "w": 13.8, "h": 84.0, "c": "prec"}, {"t": "rect", "x": 92.5, "y": 59.0, "w": 13.8, "h": 91.0, "c": "prec"}, {"t": "rect", "x": 112.3, "y": 69.5, "w": 13.8, "h": 80.5, "c": "prec"}, {"t": "rect", "x": 132.2, "y": 97.5, "w": 13.8, "h": 52.5, "c": "prec"}, {"t": "rect", "x": 152.0, "y": 104.5, "w": 13.8, "h": 45.5, "c": "prec"}, {"t": "rect", "x": 171.8, "y": 101.0, "w": 13.8, "h": 49.0, "c": "prec"}, {"t": "rect", "x": 191.7, "y": 90.5, "w": 13.8, "h": 59.5, "c": "prec"}, {"t": "rect", "x": 211.5, "y": 69.5, "w": 13.8, "h": 80.5, "c": "prec"}, {"t": "rect", "x": 231.3, "y": 62.5, "w": 13.8, "h": 87.5, "c": "prec"}, {"t": "rect", "x": 251.2, "y": 73.0, "w": 13.8, "h": 77.0, "c": "prec"}, {"t": "line", "pts": "39.9,70.0 59.7,68.4 79.6,68.4 99.4,68.4 119.2,70.0 139.1,71.6 158.9,73.2 178.7,73.2 198.6,71.6 218.4,71.6 238.2,70.0 258.1,70.0", "c": "temp"}, {"t": "line", "pts": "30,150 268,150", "c": "axis"}, {"t": "text", "x": 39.9, "y": 162, "s": "Я", "sm": true}, {"t": "text", "x": 59.7, "y": 162, "s": "Ф", "sm": true}, {"t": "text", "x": 79.6, "y": 162, "s": "М", "sm": true}, {"t": "text", "x": 99.4, "y": 162, "s": "А", "sm": true}, {"t": "text", "x": 119.2, "y": 162, "s": "М", "sm": true}, {"t": "text", "x": 139.1, "y": 162, "s": "И", "sm": true}, {"t": "text", "x": 158.9, "y": 162, "s": "И", "sm": true}, {"t": "text", "x": 178.7, "y": 162, "s": "А", "sm": true}, {"t": "text", "x": 198.6, "y": 162, "s": "С", "sm": true}, {"t": "text", "x": 218.4, "y": 162, "s": "О", "sm": true}, {"t": "text", "x": 238.2, "y": 162, "s": "Н", "sm": true}, {"t": "text", "x": 258.1, "y": 162, "s": "Д", "sm": true}, {"t": "text", "x": 78, "y": 12, "s": "Линия: температура, °C", "sm": true}, {"t": "text", "x": 205, "y": 12, "s": "Столбики: осадки, мм", "sm": true}]}}, {"id": "task-080", "sectorId": "sector-20", "type": "identify", "topic": "continents", "title": "Озеро на экваторе", "description": "Это самое большое по площади озеро Африки и одно из крупнейших озёр мира. Экватор пересекает его северную часть. Из него вытекает Белый Нил.", "question": "Определи озеро.", "hint": "Его название совпадает с именем королевы, жившей в XIX веке.", "explanation": "Это озеро Виктория. Оно лежит на плоскогорье в Восточной Африке, в тектонической впадине. Другие крупные озёра Африки — Танганьика (самое глубокое), Ньяса, Чад.", "extra": true, "complex": false, "fgos": "3.1.1", "options": ["Виктория", "Танганьика", "Ньяса", "Чад"], "correctAnswer": 0}, {"id": "task-081", "sectorId": "sector-21", "type": "multiple_choice", "topic": "continents", "title": "Река-гигант", "description": "Эта река протекает по обширной низменности близ экватора. Её бассейн занимает около 7 млн км², в неё впадает множество притоков, а по полноводности равных ей нет.", "question": "Как называется эта река?", "hint": "Река названа так же, как воинственные женщины из мифов.", "explanation": "Это Амазонка — самая полноводная река мира. Она течёт по Амазонской низменности, покрытой влажными экваториальными лесами (сельвой), и впадает в Атлантический океан.", "extra": false, "complex": false, "fgos": "3.1.1", "options": ["Амазонка", "Парана", "Ориноко", "Нил"], "correctAnswer": 0}, {"id": "task-082", "sectorId": "sector-21", "type": "map_click", "topic": "continents", "title": "Где Анды", "description": "Западная окраина Южной Америки поднята: здесь океаническая плита Наска погружается под материковую плиту. Вдоль побережья тянется высочайшая горная система материка — Анды.", "question": "Нажми на область, где расположены Анды.", "hint": "Горы возникли там, где плиты соприкасаются. Это западная окраина, на границе с Тихим океаном.", "explanation": "Анды вытянуты вдоль западного края материка на 9000 км — это самая длинная горная система на суше. В Андах много действующих вулканов и часты землетрясения. К востоку лежат Амазонская низменность и Бразильское плоскогорье.", "extra": false, "complex": false, "fgos": "3.1.5", "correctZone": "west", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "west", "label": "Западная окраина материка у Тихого океана", "x": 8, "y": 20, "w": 85, "h": 140, "c": "mount"}, {"t": "zone", "id": "centre", "label": "Центральная низменность вблизи экватора", "x": 97, "y": 20, "w": 100, "h": 140, "c": "low"}, {"t": "zone", "id": "east", "label": "Восточная часть материка, плоскогорье", "x": 201, "y": 20, "w": 91, "h": 140, "c": "hill"}, {"t": "text", "x": 150, "y": 12, "s": "Разрез материка с запада на восток", "sm": true}]}}, {"id": "task-083", "sectorId": "sector-21", "type": "analysis", "topic": "continents", "title": "Пустыня у океана", "description": "На западном побережье Южной Америки около 20° ю. ш. лежит пустыня Атакама — одно из самых сухих мест Земли. Вдоль побережья идёт холодное Перуанское течение, а на востоке стеной стоят Анды.", "question": "Как возникла эта пустыня?", "hint": "Холодная вода охлаждает воздух над ней. Что происходит с влагой в холодном воздухе?", "explanation": "Воздух над холодным течением охлаждается и опускается, поэтому над берегом нет восходящих потоков и осадков почти нет. Ветры с Атлантики теряют влагу ещё над Амазонкой и Андами. В результате на побережье возникает пустыня, где годами не бывает дождей.", "extra": false, "complex": true, "fgos": "3.1.5", "options": ["Холодное течение охлаждает воздух у берега, он стабилен и сух, а Анды задерживают влагу с востока", "Тёплое течение испаряет всю влагу", "Рядом нет ни моря, ни гор", "Здесь постоянно дуют муссоны с океана"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "rect", "x": 0, "y": 0, "w": 80, "h": 180, "c": "water"}, {"t": "rect", "x": 80, "y": 0, "w": 220, "h": 180, "c": "land"}, {"t": "poly", "pts": "180,180 230,30 280,180", "c": "mount"}, {"t": "arrow", "x1": 40, "y1": 160, "x2": 40, "y2": 30, "label": "Холодное течение"}, {"t": "text", "x": 40, "y": 172, "s": "Тихий океан", "sm": true}, {"t": "dot", "x": 125, "y": 52, "label": "Атакама"}, {"t": "text", "x": 230, "y": 22, "s": "Анды", "sm": true}]}}, {"id": "task-084", "sectorId": "sector-21", "type": "identify", "topic": "continents", "title": "Определи страну", "description": "Эта страна — крупнейшая в Южной Америке по площади и численности населения. Она занимает почти половину материка, в ней течёт Амазонка, а государственный язык — португальский.", "question": "Какая это страна?", "hint": "Португальский язык — единственный на материке, на котором говорит большинство жителей страны. Остальные страны в основном говорят по-испански.", "explanation": "Это Бразилия. Португальский язык появился здесь из-за португальской колонизации. Население — более 200 млн человек, столица — Бразилиа.", "extra": true, "complex": false, "fgos": "2.2.6", "options": ["Бразилия", "Аргентина", "Чили", "Перу"], "correctAnswer": 0}, {"id": "task-085", "sectorId": "sector-22", "type": "multiple_choice", "topic": "continents", "title": "Материк-государство", "description": "Самый маленький материк находится в Южном полушарии. Он целиком принадлежит одному государству.", "question": "Какой это материк?", "hint": "Он омывается Индийским и Тихим океанами. Столица государства — Канберра.", "explanation": "Это Австралия. Австралийский Союз — единственное государство мира, занимающее целый материк. Рядом расположены острова Океании, многие из которых также независимые государства.", "extra": false, "complex": false, "fgos": "3.1.1", "options": ["Австралия", "Антарктида", "Африка", "Южная Америка"], "correctAnswer": 0}, {"id": "task-086", "sectorId": "sector-22", "type": "map_click", "topic": "continents", "title": "Где выпадает больше дождей", "description": "Юго-восточные пассаты приносят влагу с Тихого океана. На востоке материка вдоль побережья вытянут Большой Водораздельный хребет.", "question": "Нажми на область, где выпадает больше всего осадков.", "hint": "Вспомни про наветренные склоны: куда набегают влажные ветры?", "explanation": "Влажные ветры с океана поднимаются по восточным склонам Большого Водораздельного хребта, остывают и отдают влагу. Поэтому на востоке осадков много, а в центре материка и на западных равнинах сухо: ветры теряют влагу ещё над хребтом.", "extra": false, "complex": false, "fgos": "3.1.5", "correctZone": "east", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "west", "label": "Западное плоскогорье", "x": 8, "y": 20, "w": 85, "h": 140, "c": "dry"}, {"t": "zone", "id": "centre", "label": "Центральные равнины, далеко от океанов", "x": 97, "y": 20, "w": 100, "h": 140, "c": "dry"}, {"t": "zone", "id": "east", "label": "Восточное побережье у хребта", "x": 201, "y": 20, "w": 91, "h": 140, "c": "forest"}, {"t": "arrow", "x1": 290, "y1": 12, "x2": 250, "y2": 12, "label": "Пассаты с Тихого океана"}]}}, {"id": "task-087", "sectorId": "sector-22", "type": "analysis", "topic": "continents", "title": "Сумчатые и утконосы", "description": "Австралия давно отделена от других материков. Здесь обитают кенгуру, коалы, утконосы, ехидны — животные, которых нет на других материках. Многие виды растений тоже встречаются только здесь.", "question": "Что объясняет такое богатство уникальных видов (эндемиков)?", "hint": "Эндемики — виды, обитающие только на одной территории. Подумай, как влияет на живые организмы долгая изоляция.", "explanation": "Материк длительное время был изолирован океанами от других суш, и жизнь развивалась самостоятельно. Поэтому на нём сохранились древние группы животных (сумчатые, яйцекладущие млекопитающие), а многие виды приспособились к местным условиям.", "extra": false, "complex": true, "fgos": "3.1.5", "options": ["Длительная изоляция материка океанами", "Самый влажный климат на Земле", "Присутствие в Австралии только хищников", "Отсутствие сезонных изменений"], "correctAnswer": 0}, {"id": "task-088", "sectorId": "sector-22", "type": "identify", "topic": "continents", "title": "Острова Океании", "description": "Океанию делят на три группы островов: Меланезию (на юго-западе), Микронезию (на северо-западе) и Полинезию (на востоке и в центре Тихого океана). Гавайские острова расположены в северной части Тихого океана, вблизи вершины «полинезийского треугольника».", "question": "К какой группе относятся Гавайские острова?", "hint": "Подумай, какая из трёх групп занимает центр и восток Тихого океана: Гавайи лежат севернее всех остальных островов Океании.", "explanation": "Гавайские острова входят в Полинезию. Они вулканического происхождения, возникли над «горячей точкой» в мантии. Население — потомки полинезийских мореплавателей и более поздние переселенцы.", "extra": true, "complex": false, "fgos": "3.1.1", "options": ["Полинезия", "Меланезия", "Микронезия", "Антильские острова"], "correctAnswer": 0}, {"id": "task-089", "sectorId": "sector-23", "type": "multiple_choice", "topic": "continents", "title": "Открытие шестого материка", "description": "В январе 1820 года русская экспедиция на шлюпах «Восток» и «Мирный» приблизилась к берегам неизвестной земли, покрытой льдом.", "question": "Кто возглавлял экспедицию, открывшую Антарктиду?", "hint": "Экспедиция вышла из Кронштадта в 1819 году. Вспомни русских мореплавателей начала XIX века.", "explanation": "Антарктиду открыли в 1820 году участники русской экспедиции Ф. Ф. Беллинсгаузена и М. П. Лазарева. Д. Кук в XVIII веке не нашёл материк, Р. Амундсен в 1911 году первым достиг Южного полюса, Р. Скотт — вторым в 1912 году.", "extra": false, "complex": false, "fgos": "3.1.2", "options": ["Ф. Беллинсгаузен и М. Лазарев", "Д. Кук", "Р. Амундсен", "Ф. Магеллан"], "correctAnswer": 0}, {"id": "task-090", "sectorId": "sector-23", "type": "map_click", "topic": "continents", "title": "Полюс холода", "description": "Самая низкая температура воздуха на Земле (−89,2 °C) зафиксирована в 1983 году на станции «Восток». Станция стоит на ледяном куполе высотой около 3500 м.", "question": "Нажми на часть Антарктиды, где находится станция «Восток».", "hint": "Чем выше поверхность и дальше от океана, тем холоднее. Где высота ледового щита наибольшая?", "explanation": "Станция «Восток» расположена на высоком ледяном плато Восточной Антарктиды: большая высота, удалённость от океана и полярная ночь делают климат самым суровым. Антарктический полуостров ближе к Южной Америке и самый тёплый.", "extra": false, "complex": false, "fgos": "3.1.1", "correctZone": "east", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "pen", "label": "Антарктический полуостров", "x": 8, "y": 20, "w": 82, "h": 140, "c": "ice"}, {"t": "zone", "id": "west", "label": "Западная Антарктида", "x": 94, "y": 20, "w": 80, "h": 140, "c": "ice"}, {"t": "zone", "id": "east", "label": "Восточная Антарктида, высокое плато", "x": 178, "y": 20, "w": 114, "h": 140, "c": "ice"}]}}, {"id": "task-091", "sectorId": "sector-23", "type": "analysis", "topic": "continents", "title": "Почему там так холодно", "description": "На побережье Антарктиды средняя температура около −10 °C, в центре на высоте 3500 м — около −55 °C. Ледяной щит покрывает почти весь материк, а его белая поверхность отражает большую часть солнечного света. Полярная ночь продолжается несколько месяцев.", "question": "Какие причины делают климат Антарктиды самым холодным на Земле?", "hint": "Учти три группы причин: широта, высота поверхности, подстилающая поверхность.", "explanation": "Антарктида лежит в полярных широтах (мало солнечного тепла), покрыта ледяным щитом большой высоты (с высотой холоднее), а белая поверхность отражает до 80–90 % солнечных лучей. Все три причины работают одновременно.", "extra": false, "complex": true, "fgos": "3.1.5", "options": ["Полярное положение, большая высота ледяного щита, отражение света снегом", "Близость к экватору и холодные течения", "Тёплые ветры с океана и малая высота над уровнем моря", "Влияние муссонов"], "correctAnswer": 0}, {"id": "task-092", "sectorId": "sector-23", "type": "identify", "topic": "continents", "title": "Материк науки", "description": "В 1959 году двенадцать государств, включая СССР, подписали международное соглашение: Антарктида используется только в мирных целях, запрещены военные базы и испытания оружия, обеспечивается свобода научных исследований.", "question": "Как называется этот документ?", "hint": "Название содержит название материка. Он действует с 1961 года.", "explanation": "Это Договор об Антарктике. Благодаря ему материк стал территорией научного сотрудничества: здесь работают десятки станций разных стран. Россия ведёт исследования на станциях «Восток», «Мирный», «Прогресс» и других.", "extra": true, "complex": false, "fgos": "3.1.2", "options": ["Договор об Антарктике", "Киотский протокол", "Парижское соглашение по климату", "Конвенция по морскому праву"], "correctAnswer": 0}, {"id": "task-093", "sectorId": "sector-24", "type": "multiple_choice", "topic": "continents", "title": "Граница двух материков", "description": "Северная Америка и Евразия почти соединяются на крайнем северо-востоке Евразии и северо-западе Северной Америки. Их разделяет узкий водный путь между Чукоткой и Аляской.", "question": "Как называется этот пролив?", "hint": "Он назван в честь датчанина на русской службе, который прошёл здесь в 1728 году.", "explanation": "Это Берингов пролив. Он соединяет Северный Ледовитый и Тихий океаны и разделяет Евразию и Северную Америку. Его ширина в самом узком месте — около 86 км.", "extra": false, "complex": false, "fgos": "3.2.1", "options": ["Берингов пролив", "Магелланов пролив", "Гибралтарский пролив", "Дрейка пролив"], "correctAnswer": 0}, {"id": "task-094", "sectorId": "sector-24", "type": "map_click", "topic": "continents", "title": "Вулканы и землетрясения", "description": "Северная Америка расположена на Северо-Американской плите. Вдоль её западного края проходит граница с Тихоокеанской плитой, вдоль востока — спокойный пассивный край материка (Аппалачи — старые горы).", "question": "Нажми на область, где чаще всего происходят землетрясения и действуют вулканы.", "hint": "Вспомни, где лежат границы литосферных плит и Тихоокеанское огненное кольцо.", "explanation": "Кордильеры на западе материка — молодые горы на границе плит. Здесь действуют вулканы и часты землетрясения (разлом Сан-Андреас в Калифорнии). Великие равнины в центре и древние Аппалачи на востоке находятся вдали от границы плит и намного спокойнее.", "extra": false, "complex": false, "fgos": "1.2.2", "correctZone": "west", "diagram": {"viewBox": "0 0 300 180", "compass": true, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "west", "label": "Кордильеры на западе", "x": 8, "y": 20, "w": 85, "h": 140, "c": "mount"}, {"t": "zone", "id": "centre", "label": "Великие равнины в центре материка", "x": 97, "y": 20, "w": 100, "h": 140, "c": "low"}, {"t": "zone", "id": "east", "label": "Аппалачи на востоке", "x": 201, "y": 20, "w": 91, "h": 140, "c": "hill"}]}}, {"id": "task-095", "sectorId": "sector-24", "type": "analysis", "topic": "continents", "title": "Две широты, два климата", "description": "Город А находится на тихоокеанском побережье Северной Америки (38° с. ш.): средняя температура января +10 °C, июля +17 °C. Город Б лежит на атлантическом побережье примерно на той же широте (40° с. ш.): января 0 °C, июля +25 °C. Преобладающие ветры в умеренных широтах — западные.", "question": "Почему годовая амплитуда температур в городе А (7 °C) намного меньше, чем в городе Б (25 °C)?", "hint": "Западные ветры приходят в город А прямо с океана, а в город Б — через весь материк.", "explanation": "Западный перенос приносит в город А воздух с океана: вода нагревается и остывает медленно, поэтому зима мягкая, лето прохладное. В город Б воздух приходит с материка: зимой он очень холодный, летом жаркий. К тому же вдоль берега города А проходит холодное Калифорнийское течение.", "extra": false, "complex": true, "fgos": "1.3.6", "options": ["Город А находится на западном берегу, где океанический воздух смягчает зиму и лето", "Город А расположен ближе к экватору", "В городе Б дуют пассаты", "Город Б расположен намного выше над уровнем моря"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "text", "x": 150, "y": 26, "s": "Город А (тихоокеанский берег)", "sm": true}, {"t": "text", "x": 150, "y": 46, "s": "январь +10 °C; июль +17 °C"}, {"t": "text", "x": 150, "y": 96, "s": "Город Б (материк)", "sm": true}, {"t": "text", "x": 150, "y": 116, "s": "январь 0 °C; июль +25 °C"}, {"t": "text", "x": 150, "y": 160, "s": "Обе точки на широте около 38–40° с. ш.", "sm": true}]}}, {"id": "task-096", "sectorId": "sector-24", "type": "identify", "topic": "continents", "title": "Озёра на границе стран", "description": "Это крупнейшая в мире система пресных озёр по общей площади. Пять озёр (Верхнее, Мичиган, Гурон, Эри, Онтарио) лежат на границе США и Канады (Мичиган целиком принадлежит США).", "question": "Как называется эта система озёр?", "hint": "Название отражает размеры, а озёра имеют ледниковое происхождение.", "explanation": "Это Великие озёра. Они лежат в глубоких котловинах, оставленных материковым ледником. Через озеро Онтарио и реку Святого Лаврентия они соединены с Атлантическим океаном.", "extra": true, "complex": false, "fgos": "3.2.1", "options": ["Великие озёра", "Озёра Рудольфа и Эдуард", "Озёра Байкал и Ладожское", "Озёра Чад и Эйр"], "correctAnswer": 0}, {"id": "task-097", "sectorId": "sector-25", "type": "multiple_choice", "topic": "continents", "title": "Части света", "description": "Евразия — самый большой материк планеты. По исторически сложившемуся делению на нём выделяют две части света.", "question": "Какие две части света образуют материк Евразия?", "hint": "Граница между ними проходит по Уральским горам.", "explanation": "Евразия включает Европу и Азию. Условная граница между ними проходит по Уральским горам, реке Урал, Каспийскому морю, Кумо-Манычской впадине и проливам Босфор и Дарданеллы.", "extra": false, "complex": false, "fgos": "3.2.1", "options": ["Европа и Азия", "Европа и Африка", "Азия и Австралия", "Европа и Северная Америка"], "correctAnswer": 0}, {"id": "task-098", "sectorId": "sector-25", "type": "map_click", "topic": "continents", "title": "Одна широта, разный климат", "description": "В умеренном поясе вдоль 55° с. ш. климат меняется с запада на восток: у океанов зимы мягкие, а в глубине материка — суровые. Амплитуда (разница средних температур июля и января) в Западной Европе около 10–20 °C, на Дальнем Востоке около 30–35 °C, а в Якутии около 55–60 °C.", "question": "Нажми на область с самой большой годовой амплитудой температур.", "hint": "Подумай, где воздух максимально удалён от океанов и сильнее всего выхолаживается зимой.", "explanation": "В Восточной Сибири (Якутия) климат резко континентальный: зимой температура опускается ниже −50 °C, летом бывает +30 °C. Океан здесь далеко, воздух не смягчается. На западной окраине Атлантика и тёплое течение смягчают зиму, а на восточной сказывается влияние Тихого океана.", "extra": false, "complex": false, "fgos": "1.3.6", "correctZone": "sib", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "west", "label": "Западная Европа, у Атлантики", "x": 8, "y": 20, "w": 85, "h": 140, "c": "forest"}, {"t": "zone", "id": "sib", "label": "Восточная Сибирь, в глубине материка", "x": 97, "y": 20, "w": 100, "h": 140, "c": "cold"}, {"t": "zone", "id": "far", "label": "Дальний Восток, у Тихого океана", "x": 201, "y": 20, "w": 91, "h": 140, "c": "low"}, {"t": "text", "x": 150, "y": 12, "s": "Вдоль 55° с. ш. с запада на восток", "sm": true}]}}, {"id": "task-099", "sectorId": "sector-25", "type": "analysis", "topic": "continents", "title": "Япония и Восточно-Европейская равнина", "description": "Япония расположена на границе Евразийской и Тихоокеанской плит, там ежегодно фиксируют тысячи землетрясений, действует более 100 вулканов. Восточно-Европейская равнина лежит в центре Евразийской плиты на древней платформе, и сильных землетрясений там практически не бывает.", "question": "Как объяснить различия в сейсмичности?", "hint": "Вспомни, где происходит больше всего землетрясений: у границ плит или в их середине.", "explanation": "Япония находится на границе плит (зона субдукции), где идёт постоянное движение земной коры. Восточно-Европейская равнина расположена внутри плиты на древней устойчивой платформе, поэтому там спокойно. Это подтверждает закономерность: землетрясения и вулканы приурочены к границам плит.", "extra": false, "complex": true, "fgos": "1.2.2", "options": ["Япония лежит на границе литосферных плит, а равнина — в центре древней платформы", "В Японии больше людей, поэтому землетрясения замечают чаще", "Равнина слишком влажная для землетрясений", "В Японии нет гор"], "correctAnswer": 0, "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "rect", "x": 0, "y": 30, "w": 170, "h": 120, "c": "land"}, {"t": "rect", "x": 170, "y": 30, "w": 130, "h": 120, "c": "water"}, {"t": "text", "x": 85, "y": 110, "s": "Евразийская плита"}, {"t": "text", "x": 236, "y": 100, "s": "Тихоокеанская", "sm": true}, {"t": "text", "x": 236, "y": 114, "s": "плита", "sm": true}, {"t": "arrow", "x1": 290, "y1": 130, "x2": 175, "y2": 130, "label": ""}, {"t": "dot", "x": 40, "y": 70, "label": "Равнина"}, {"t": "dot", "x": 165, "y": 70, "label": "Япония"}]}}, {"id": "task-100", "sectorId": "sector-25", "type": "identify", "topic": "continents", "title": "Глубочайшее озеро мира", "description": "Это озеро расположено в Сибири, в рифтовой впадине. Его глубина — около 1640 м. В нём содержится примерно пятая часть мировых запасов поверхностной пресной воды.", "question": "Определи озеро.", "hint": "Из перечисленных озёр только одно лежит в Сибири.", "explanation": "Это Байкал: самое глубокое озеро мира (1642 м) и крупнейший природный резервуар пресной воды. Озеро включено в список Всемирного наследия ЮНЕСКО.", "extra": true, "complex": false, "fgos": "3.2.1", "options": ["Байкал", "Ладожское", "Каспийское", "Аральское"], "correctAnswer": 0}, {"id": "task-101", "sectorId": "sector-26", "type": "multiple_choice", "topic": "society", "title": "Нехватка еды", "description": "Во многих странах Азии и Африки миллионы людей постоянно недоедают. Причины: бедность, засухи, войны, быстрый рост населения.", "question": "К какой глобальной проблеме человечества относится эта ситуация?", "hint": "Проблема связана с обеспеченностью людей пищей.", "explanation": "Это продовольственная проблема. Другие глобальные проблемы: экологическая (загрязнение, изменение климата), сырьевая и энергетическая (исчерпаемость ресурсов), преодоление отсталости стран. Цели устойчивого развития ООН включают «Ликвидацию голода».", "extra": false, "complex": false, "fgos": "3.3.3", "options": ["Продовольственная", "Энергетическая", "Сырьевая", "Демографического старения"], "correctAnswer": 0}, {"id": "task-102", "sectorId": "sector-26", "type": "map_click", "topic": "society", "title": "Всемирное наследие", "description": "Большой Барьерный риф — крупнейшая система коралловых рифов планеты. Он включён в список Всемирного наследия ЮНЕСКО как уникальный природный объект. На схеме показаны четыре области.", "question": "Нажми на область, где находится Большой Барьерный риф.", "hint": "Риф протянулся вдоль побережья материка, омываемого Коралловым морем.", "explanation": "Большой Барьерный риф расположен у северо-восточных берегов Австралии, в Коралловом море. Он тянется более чем на 2000 км. В списке Всемирного наследия есть и культурные, и природные объекты, которые нужно беречь всем человечеством.", "extra": false, "complex": false, "fgos": "3.3.2", "correctZone": "aus", "diagram": {"viewBox": "0 0 300 180", "compass": false, "items": [{"t": "rect", "x": 0, "y": 0, "w": 300, "h": 180, "c": "card"}, {"t": "zone", "id": "sahara", "label": "Центральная Сахара", "x": 8, "y": 8, "w": 140, "h": 76, "c": "sand"}, {"t": "zone", "id": "aus", "label": "Северо-восток Австралии", "x": 152, "y": 8, "w": 140, "h": 76, "c": "dry"}, {"t": "zone", "id": "amazon", "label": "Бассейн Амазонки", "x": 8, "y": 90, "w": 140, "h": 80, "c": "eq"}, {"t": "zone", "id": "scand", "label": "Скандинавия", "x": 152, "y": 90, "w": 140, "h": 80, "c": "taiga"}]}}, {"id": "task-103", "sectorId": "sector-26", "type": "analysis", "topic": "society", "title": "Исчезающее море", "description": "Аральское море в Центральной Азии в 1960 году было четвёртым по площади озером мира. Воды питавших его рек (Амударья и Сырдарья) стали отводить на орошение хлопка и риса. К началу XXI века его площадь сократилась в несколько раз, солёность воды резко выросла, рыбные промыслы закрылись, а на месте дна образовалась солончаковая пустыня.", "question": "Что стало главной причиной катастрофы?", "hint": "Подумай, куда стала уходить вода рек, которые раньше впадали в море.", "explanation": "Главная причина — забор воды из рек на орошение. Море почти не получало воды, а испарялось по-прежнему, и его уровень падал. Это пример того, как хозяйственная деятельность меняет природные комплексы, гидросферу и климат региона.", "extra": false, "complex": true, "fgos": "3.3.4", "options": ["Забор воды из питающих рек на орошение", "Землетрясение разрушило дно", "Тёплое течение повысило испарение", "Горные ледники растаяли, и реки исчезли сами"], "correctAnswer": 0}, {"id": "task-104", "sectorId": "sector-26", "type": "identify", "topic": "society", "title": "Цели на 2030 год", "description": "В 2015 году все государства — члены этой организации приняли 17 Целей устойчивого развития до 2030 года: ликвидация нищеты и голода, чистая вода, борьба с изменением климата, сохранение океанов и лесов.", "question": "Какая международная организация приняла эти цели?", "hint": "Её штаб-квартира находится в Нью-Йорке. В её состав входят почти все страны мира.", "explanation": "Это Организация Объединённых Наций (ООН). Решить глобальные проблемы одной стране не под силу, поэтому ООН и её органы (ЮНЕСКО, ЮНЕП и др.) координируют международные усилия.", "extra": true, "complex": false, "fgos": "3.3.3", "options": ["ООН", "ЮНЕСКО", "Международный союз охраны природы", "Всемирный банк"], "correctAnswer": 0}], "discoveries": [{"id": "discovery-013", "name": "Три свойства оболочки", "category": "Закономерности", "short": "Целостность, зональность и ритмичность.", "long": "Компоненты оболочки связаны между собой, природные зоны сменяются от экватора к полюсам (а в горах — с высотой), а суточные и годовые ритмы повторяются.", "sectors": ["sector-13"], "condition": {"type": "sectorExplored", "sector": "sector-13"}}, {"id": "discovery-014", "name": "Движение литосферных плит", "category": "Рельеф", "short": "На границах плит возникают горы, вулканы и землетрясения.", "long": "Литосферные плиты движутся на несколько сантиметров в год. Сближаясь, они образуют горы и глубоководные жёлоба, а в центре плит лежат спокойные платформы.", "sectors": ["sector-14"], "condition": {"type": "sectorExplored", "sector": "sector-14"}}, {"id": "discovery-015", "name": "Пояса давления и ветры", "category": "Климат", "short": "Ветер дует из области высокого давления в область низкого.", "long": "У экватора давление низкое, в тропиках высокое. Отсюда пассаты, а в умеренных широтах — западные ветры. Над материками и океанами сезонно меняют направление муссоны.", "sectors": ["sector-15"], "condition": {"type": "sectorExplored", "sector": "sector-15"}}, {"id": "discovery-016", "name": "Климатограмма — паспорт климата", "category": "Климат", "short": "График показывает температуру и осадки по месяцам.", "long": "По климатограмме можно определить климатический пояс: экваториальный климат без сезонов, средиземноморский — с сухим летом и дождливой зимой.", "sectors": ["sector-16"], "condition": {"type": "sectorExplored", "sector": "sector-16"}}, {"id": "discovery-017", "name": "Течения и солёность", "category": "Воды", "short": "Течения переносят тепло, солёность зависит от испарения.", "long": "Тёплые течения смягчают климат побережий, холодные охлаждают. Самая высокая солёность — в тропиках, где много испарения и мало осадков.", "sectors": ["sector-17"], "condition": {"type": "sectorExplored", "sector": "sector-17"}}, {"id": "discovery-018", "name": "Неравномерность размещения людей", "category": "Человечество", "short": "Плотность населения резко различается.", "long": "Больше всего людей живёт на равнинах у рек, в умеренных и тёплых широтах. Пустыни, горы и полярные области почти безлюдны.", "sectors": ["sector-18"], "condition": {"type": "sectorExplored", "sector": "sector-18"}}, {"id": "discovery-019", "name": "Языки, религии и занятия", "category": "Человечество", "short": "Народы различаются языком, верой и хозяйством.", "long": "Народы объединяют в языковые семьи, религии распространены неравномерно, а занятость населения показывает уровень развития страны.", "sectors": ["sector-19"], "condition": {"type": "sectorExplored", "sector": "sector-19"}}, {"id": "discovery-020", "name": "Симметрия природных зон Африки", "category": "Материки", "short": "Зоны сменяются симметрично от экватора.", "long": "От экватора к северу и югу влажные леса сменяются саваннами и пустынями — Сахарой на севере, Калахари и Намибом на юге.", "sectors": ["sector-20"], "condition": {"type": "sectorExplored", "sector": "sector-20"}}, {"id": "discovery-021", "name": "Холодное течение и пустыня", "category": "Материки", "short": "У западного берега Южной Америки лежит пустыня Атакама.", "long": "Холодное Перуанское течение охлаждает воздух, а Анды задерживают влажные ветры с востока: осадков почти нет.", "sectors": ["sector-21"], "condition": {"type": "sectorExplored", "sector": "sector-21"}}, {"id": "discovery-022", "name": "Изоляция и эндемики", "category": "Материки", "short": "В Австралии много видов, которых нет нигде больше.", "long": "Долгая изоляция материка позволила сохраниться сумчатым и яйцекладущим млекопитающим.", "sectors": ["sector-22"], "condition": {"type": "sectorExplored", "sector": "sector-22"}}, {"id": "discovery-023", "name": "Материк науки", "category": "Материки", "short": "Антарктида используется только в мирных целях.", "long": "Договор об Антарктике (1959) закрепил свободу научных исследований, запретил военную деятельность и сохранил материк как территорию сотрудничества.", "sectors": ["sector-23"], "condition": {"type": "sectorExplored", "sector": "sector-23"}}, {"id": "discovery-024", "name": "Рельеф и воздушные массы", "category": "Материки", "short": "Вытянутый с севера на юг рельеф открывает путь воздушным массам.", "long": "На Великих равнинах нет гор, преграждающих путь: арктический воздух может доходить на юг, а тропический — на север, поэтому здесь резкие смены погоды.", "sectors": ["sector-24"], "condition": {"type": "sectorExplored", "sector": "sector-24"}}, {"id": "discovery-025", "name": "Континентальность Евразии", "category": "Материки", "short": "Чем дальше от океана, тем резче климат.", "long": "В Восточной Сибири зимы суровые, а лето тёплое: океан слишком далеко, чтобы смягчить колебания температуры.", "sectors": ["sector-25"], "condition": {"type": "sectorExplored", "sector": "sector-25"}}, {"id": "discovery-026", "name": "Глобальные проблемы требуют сотрудничества", "category": "Природа и общество", "short": "Проблемы человечества решают вместе.", "long": "Экологическая, сырьевая, энергетическая и продовольственная проблемы выходят за границы стран, поэтому нужны международные организации и общие цели.", "sectors": ["sector-26"], "condition": {"type": "sectorExplored", "sector": "sector-26"}}], "achievements": [{"id": "c2-shell", "chapter": 2, "name": "Целостный взгляд", "description": "Исследована географическая оболочка.", "condition": {"type": "sectorExplored", "sector": "sector-13"}}, {"id": "c2-first", "chapter": 2, "name": "Первые открытия Земли", "description": "Найдено пять географических открытий главы 2.", "condition": {"type": "discoveryCount", "n": 5}}, {"id": "c2-wind", "chapter": 2, "name": "Знаток ветров", "description": "Решены три задачи об атмосфере.", "condition": {"type": "topicTasks", "topic": "atmo", "n": 3}}, {"id": "c2-ocean", "chapter": 2, "name": "Капитан течений", "description": "Исследован Мировой океан.", "condition": {"type": "sectorExplored", "sector": "sector-17"}}, {"id": "c2-people", "chapter": 2, "name": "Демограф", "description": "Исследовано население Земли.", "condition": {"type": "sectorExplored", "sector": "sector-18"}}, {"id": "c2-continents", "chapter": 2, "name": "Путешественник по материкам", "description": "Решены двенадцать задач о материках.", "condition": {"type": "topicTasks", "topic": "continents", "n": 12}}, {"id": "c2-full", "chapter": 2, "name": "Дотошный исследователь Земли", "description": "Одна зона изучена полностью.", "condition": {"type": "fullCount", "n": 1}}, {"id": "c2-all", "chapter": 2, "name": "Вся Земля", "description": "Исследованы все 14 зон Большой карты.", "condition": {"type": "exploredCount", "n": 14}}]}};
